'Custom_SMS_Payload_Hint' => 'Defina los campos del cuerpo de la solicitud. Use {phone}, {message} y {sender} como marcadores; se reemplazarán en el momento del envío.',
'Custom_SMS_Guide_Title' => 'Cómo configurar',
'Custom_SMS_Guide_Intro' => 'Se puede conectar cualquier proveedor de SMS con una API HTTP. Abra la documentación de la API de su proveedor, copie el endpoint, el método y los nombres de los campos, y luego asígnelos abajo usando los marcadores.',
'Custom_SMS_Guide_Placeholder_Phone' => 'el número de teléfono del destinatario',
'Custom_SMS_Guide_Placeholder_Message' => 'el texto del SMS',
'Custom_SMS_Guide_Placeholder_Sender' => 'el ID de remitente introducido arriba',
'Custom_SMS_Guide_Api_Url' => 'La URL completa del endpoint según la documentación de su proveedor, p. ej., https://api.provider.com/sms/send. También se permiten marcadores directamente en la URL, p. ej., ...?to={phone}&text={message}.',
'Custom_SMS_Guide_Method' => 'POST es el más habitual. Elija GET solo si su proveedor espera todo en la URL; en ese caso, los campos del cuerpo se envían como parámetros de consulta.',
'Custom_SMS_Guide_Content_Type' => '"json" envía el cuerpo como JSON (application/json). "form" lo envía como un formulario HTML clásico (application/x-www-form-urlencoded). Compruebe cuál espera su proveedor; se ignora con GET.',
'Custom_SMS_Guide_Sender' => 'Su ID de remitente aprobado o número de teléfono de envío. Solo rellena el marcador {sender}; para que se transmita, debe usarse en el cuerpo, los encabezados o la URL.',
'Custom_SMS_Guide_Success_Keyword' => 'Opcional, pero recomendado. Algunos proveedores responden "200 OK" incluso cuando el envío falla. Introduzca una palabra o fragmento que solo aparezca en una respuesta correcta (p. ej., success). Si la respuesta no lo contiene, el SMS se considera fallido.',
'Custom_SMS_Guide_Headers' => 'Encabezados de autenticación que exige su proveedor, p. ej., Authorization = Bearer YOUR_API_KEY, o Api-Key = YOUR_API_KEY. No añada Content-Type: se establece automáticamente.',
'Custom_SMS_Guide_Payload' => 'Los campos del cuerpo de la solicitud, con los nombres exactos de la documentación de su proveedor. Use los marcadores como valores, p. ej., to = {phone}, message = {message}, from = {sender}.',
'Custom_SMS_Guide_Example' => 'Ejemplo completo',
'Custom_SMS_Guide_Default_Note' => 'Después de guardar, seleccione "custom" como pasarela SMS predeterminada en la parte superior de esta página y envíe el formulario; de lo contrario, los SMS seguirán usando la pasarela seleccionada anteriormente.',
