'Cr_Guide_T_Statuses' => 'Estados',
'Cr_Guide_Statuses_Note' => 'Los estados solo avanzan, así que una actualización tardía nunca hace retroceder un paquete. Un paquete entregado aún puede notificarse como en devolución o devuelto.',
'Cr_Guide_S_booked' => 'La mensajería tiene el pedido; nadie lo ha recogido todavía. Solo en este momento se puede cancelar un envío.',
