'Cr_Guide_S_in_transit' => 'En tránsito entre centros, en aduanas o retenido.',
'Cr_Guide_S_out_for_delivery' => 'Con el repartidor hoy.',
'Cr_Guide_S_failed_attempt' => 'Nadie en el domicilio, rechazado o dirección incorrecta. El transportista lo intenta de nuevo o lo devuelve.',
'Cr_Guide_S_delivered' => 'Entregado al cliente. El importe contra entrega pasa a cobrado por el transportista.',
'Cr_Guide_S_returning' => 'De camino de vuelta a usted.',
'Cr_Guide_S_returned' => 'De vuelta con usted: espera en Devoluciones por revisar o se repone en el stock automáticamente.',
'Cr_Guide_S_cancelled' => 'La reserva se canceló.',
'Cr_Guide_T_Booking' => 'Reservar envíos',
'Cr_Guide_B_Booking' => 'Enviar a mensajería rellena el formulario a partir de la venta: destinatario, dirección, el importe aún pendiente como cobro contra entrega y el peso de los productos. Los transportistas con su propia lista de ciudades muestran un selector, y su elección se recuerda para esa ciudad. Los agregadores, DHL, FedEx, UPS y Lalamove ofrecen Comparar tarifas: elija un precio y Reservar lo contrata. Se pueden reservar varias ventas a la vez desde la lista de ventas.',
'Cr_Guide_T_Cod' => 'Pago contra entrega',
'Cr_Guide_B_Cod' => 'Un paquete contra entrega pasa de No cobrado a Cobrado por el transportista (en la entrega) y a Liquidado a usted. Los transportistas que informan de sus liquidaciones completan el último paso por sí mismos; para los demás, use Actualizar contra entrega. Con una cuenta elegida en Configuración de mensajería, cada liquidación se registra como un pago de la venta. Los cargos del transportista pueden guardarse como gasto cuando el paquete ha finalizado.',
'Cr_Guide_T_Returns' => 'Paquetes devueltos',
'Cr_Guide_B_Returns' => 'De forma predeterminada, un paquete devuelto espera en Envíos de mensajería, en Devoluciones por revisar. Reponer crea una devolución de venta de todo el pedido y vuelve a poner los artículos en stock; Descartar no repone nada, para paquetes dañados o perdidos. También puede configurar la reposición automática en Configuración de mensajería.',
'Cr_Guide_T_Customers' => 'Mensajes a clientes y página de seguimiento',
'Cr_Guide_B_Customers' => 'Las notificaciones a clientes de Configuración de mensajería envían SMS, correo electrónico o WhatsApp en los estados que marque, una sola vez por paquete y con su propio texto. La página de seguimiento de su tienda online permite a los clientes seguir un paquete por número de seguimiento, o por número de pedido y teléfono. Los clientes que devuelven paquetes con frecuencia muestran una insignia de riesgo de devolución al reservar.',
'Cr_Guide_T_Labels' => 'Etiquetas',
'Cr_Guide_B_Labels' => 'Imprimir etiqueta ofrece la etiqueta propia del transportista cuando la emite (un PDF, un enlace o una imagen); si no, una etiqueta de Stocky con el código de barras de seguimiento y el importe a cobrar. Permita las ventanas emergentes de este sitio para imprimir. DHL, FedEx y UPS entregan su etiqueta una sola vez, al reservar, y Stocky la conserva para reimprimirla.',
'Cr_Guide_T_Faq' => 'Solución de problemas',
'Cr_Guide_Q_Test' => 'Falla la prueba de conexión',
'Cr_Guide_A_Test' => 'Las claves de prueba se usan con el modo de prueba y las claves de producción con Producción; son distintas. Abra los Registros de mensajería y lea la respuesta del transportista para conocer el motivo exacto.',
'Cr_Guide_Q_City' => 'El transportista rechaza la ciudad o la dirección',
'Cr_Guide_A_City' => 'Elija la ciudad de la lista de ciudades del transportista en el formulario de reserva; los transportistas solo aceptan sus propios nombres. Los transportistas que trabajan con direcciones postales también necesitan el estado o provincia, el código postal y el país en dos letras.',
'Cr_Guide_Q_Webhook' => 'Los estados no cambian por sí solos',
'Cr_Guide_A_Webhook' => 'En los transportistas que envían actualizaciones, compruebe que la URL del webhook está registrada en el transportista: los Registros de mensajería muestran cada actualización recibida o por qué se rechazó (por ejemplo, un secreto incorrecto). Los demás transportistas se consultan según la programación de Configuración de mensajería, y Comprobar estado ahora consulta al instante.',
'Cr_Guide_Q_Stuck' => 'Un envío muestra un error de comprobación de estado',
'Cr_Guide_A_Stuck' => 'El transportista rechazó las últimas comprobaciones; el motivo figura en el envío y en los Registros de mensajería. Tras varios fallos seguidos, el envío deja de comprobarse automáticamente: corrija la causa y luego use Comprobar estado ahora.',
'Cr_Guide_Q_Label' => 'No se abre nada al imprimir una etiqueta',
'Cr_Guide_A_Label' => 'Su navegador bloqueó la ventana emergente. Permita las ventanas emergentes de este sitio e inténtelo de nuevo.',
'Cr_Guide_Q_Cod' => 'Una liquidación contra entrega no se registró en la venta',
'Cr_Guide_A_Cod' => 'En Configuración de mensajería, el pago contra entrega necesita el interruptor activado y una cuenta elegida. Sin cuenta, las liquidaciones solo se marcan como liquidadas.',
