'Restrict_Master_Data_By_Warehouse' => 'Restringir datos maestros por almacén',
'Restrict_Master_Data_By_Warehouse_Help' => 'Si está activado, un usuario asignado a almacenes concretos solo ve los productos, clientes, proveedores, marcas y categorías vinculados a esos almacenes. Los registros que aún no se han usado en ningún sitio siguen visibles, por lo que los recién creados nunca quedan ocultos. Las ventas, compras y devoluciones siempre están restringidas y no dependen de este interruptor.',
'Restrict_Products_By_Warehouse' => 'Restringir productos por almacén',
'Restrict_Products_By_Warehouse_Help' => 'Cada producto tiene un almacén de origen: la sucursal para la que se creó. Si está activado, un usuario asignado a almacenes concretos solo ve, vende y edita los productos cuyo almacén de origen es uno de los suyos, además de los productos con stock real en alguno de sus almacenes (transferido o comprado). Los usuarios con acceso a todos los almacenes siempre lo ven todo. La tienda online sigue la misma regla: solo muestra los productos de los almacenes seleccionados en la Configuración de la tienda.',
'Virtual_Combo_Stock' => 'Stock virtual de combos',
'Virtual_Combo_Stock_Help' => 'Si está activado, un producto combo no tiene stock propio: su disponibilidad es el número de combos que aún pueden completar sus productos componentes, y vender un combo descuenta stock de los componentes. Si está desactivado, los combos se ensamblan primero en stock mediante un Ajuste.',
'Virtual_Combo_Stock_Warning' => 'Conviene elegirlo antes de vender combos. Si se cambia después de haber vendido o devuelto combos, las ediciones, eliminaciones y devoluciones posteriores de esos documentos revertirán su stock en el sentido equivocado.',
'Virtual_Combo_Stock_Confirm_On_Title' => '¿Activar el stock virtual de combos?',
'Virtual_Combo_Stock_Confirm_On_Body' => 'Los combos se venderán directamente desde sus productos componentes y su propio stock dejará de usarse.',
'Virtual_Combo_Stock_Confirm_Off_Title' => '¿Desactivar el stock virtual de combos?',
'Virtual_Combo_Stock_Confirm_Off_Body' => 'Los combos volverán a usar su propio stock, que deberá ensamblarse a partir de los componentes con un Ajuste antes de poder venderlos.',
'Home_Warehouse' => 'Almacén de origen',
'Home_Warehouse_Hint' => 'La sucursal a la que pertenece este producto. Los usuarios restringidos a otros almacenes no lo verán, salvo que se les transfiera stock.',
'Home_Warehouse_Required' => 'Elija el almacén al que pertenece este producto.',
'Combo_products_required' => 'Añada al menos un producto al combo.',
'Customer_Performance_Help' => 'Mostrar una puntuación y una calificación de rendimiento en la página del cliente, calculadas a partir de su fiabilidad de pago, lo reciente de sus compras y su tasa de devolución.',
'Product_Supplier' => 'Proveedor en los productos',
'Product_Supplier_Help' => 'Añade un campo de proveedor predeterminado al formulario de producto, lo muestra como columna en la lista de productos y permite filtrar los productos por proveedor para preparar una lista de reposición.',
'Default_Supplier_Hint' => 'El proveedor al que normalmente vuelve a pedir este producto. Filtre la lista de productos por proveedor para ver todo lo que debe pedirle.',
'Account_Ledger' => 'Libro mayor de la cuenta',
'Closing_Balance' => 'Saldo final',
'Recon_Intro' => 'Compara el saldo operativo de cada cuenta de caja y banco con el saldo del Libro Mayor de su cuenta contable vinculada. Esta página es de solo lectura: nunca modifica ninguno de los dos saldos.',
'Recon_Auto_Off' => 'Los asientos automáticos están desactivados, por lo que las nuevas transacciones no se registran en el Libro Mayor y aparecerán como asientos faltantes. Actívelos en Configuración → Activación de funciones.',
