'Tg_Guide_A_Title' => 'Al instante — sin nada que instalar',
'Tg_Guide_A_Body' => 'Una venta, compra, pago o gasto guardado en Stocky — en el POS o en la administración — se envía a Telegram {rightAfter} guardarse, en la misma solicitud. Sin entrada cron ni procesos de cola, y el cajero nunca espera a Telegram: la venta ya se ha respondido cuando sale el mensaje.',
'Tg_Guide_Right_After' => 'justo después de',
'Tg_Guide_B_Title' => 'La entrada cron — para reintentos y eventos en segundo plano',
'Tg_Guide_B_Body' => 'Dos tipos de mensajes esperan, en cambio, en la cola propia de Telegram: un envío que falló (Telegram no disponible por un momento), que se reintenta hasta tres veces más en los minutos siguientes; y los eventos generados fuera de la administración — pedidos importados de WooCommerce o Shopify, comandos de artisan. Esta entrada cron los envía, y nada más:',
'Tg_Guide_B_Note' => 'Cada minuto es lo adecuado: una ejecución sin nada pendiente termina de inmediato. En cPanel esto va en {cronJobs} — use la ruta completa a PHP 8.2+ si {php} es más antiguo. En Windows, use el Programador de tareas con el programa {php2}, los argumentos {args} e iniciando en {path}.',
'Tg_Guide_N_Waiting' => '{n} pendientes de envío',
'Tg_Guide_Nothing_Waiting' => 'nada pendiente',
'Tg_Guide_N_Gave_Up' => '{n} descartados tras los reintentos',
'Tg_Guide_Growing_Hint' => '— si este número no deja de crecer, la entrada cron no se está ejecutando.',
'Tg_Guide_Without_Cron' => 'Sin la entrada cron, todo lo que se guarda en Stocky sigue llegando al instante; solo se pierden los reintentos y los pedidos importados.',
'Tg_Guide_Else_Title' => 'Todo lo demás',
'Tg_Guide_Else_Body' => 'Los mensajes de eventos generados en segundo plano los entrega la plataforma — no hay nada que configurar.',
'Tg_Guide_Not_Arrive' => 'Si no llega',
'Tg_Guide_Err_401' => '{code} — el token del bot es incorrecto. Péguelo de nuevo desde BotFather.',
'Tg_Guide_Err_400' => '{code} — ID de chat incorrecto, o el bot no está en el grupo. Para un chat personal, escriba primero al bot.',
'Tg_Guide_Err_403' => '{code} — vuelva a añadir el bot al grupo, o como administrador del canal.',
'Tg_Guide_Test_Works' => 'La prueba funciona pero las ventas no',
'Tg_Guide_Test_Works_Item' => '{label} — compruebe que el evento está marcado (o que {allEvents} está elegido) y que el interruptor está activado.',
'Tg_Guide_Imported_Never' => 'Los pedidos importados nunca llegan',
'Tg_Guide_Imported_Never_Item' => '{label} — la entrada cron de arriba no se está ejecutando.',
'Jumia_Hero_Title' => 'Sincronización con el marketplace Jumia',
'Jumia_Hero_Desc' => 'Envíe precios y stock a sus anuncios de Jumia Seller Center e importe los pedidos del marketplace como ventas.',
'Jumia_Api_Url_Label' => 'URL de la API (el endpoint de Seller Center de su país)',
'Jumia_Account_Email' => 'Correo electrónico de la cuenta (User ID)',
'Jumia_Prices_Stock' => 'Precios y stock',
'Jumia_Push_Card_Title' => 'Enviar precios y stock a Jumia',
'Jumia_Push_Desc' => 'Envía el precio y la cantidad actuales de cada producto (y variante) cuyo SKU coincida con el {sellerSku} del anuncio de Jumia. Las actualizaciones se envían como feeds de Seller Center y se aplican de forma asíncrona — el ID del feed queda registrado en la pestaña Registros, y los rechazos por artículo aparecen en la pantalla de estado de feeds de Seller Center.',
'Jumia_Push_Prices_Stock' => 'Enviar precios y stock',
'Jumia_Orders_Desc' => 'Importa los pedidos del marketplace como ventas (referencias como {ref}), asociados a sus productos por Seller SKU. Los pedidos ya importados y los cancelados se omiten, así que es seguro obtenerlos con regularidad. Los pagos se marcan como pagados solo en los pedidos entregados (en Jumia predomina el pago contra entrega).',
'Jumia_Guide_1' => 'En {sellerCenter} de Jumia, abra Settings → {integrationMgmt} y genere una clave API.',
'Jumia_Guide_2' => 'Introduzca la URL de la API de su país (p. ej., {ng} para Nigeria, {ke} para Kenia, {eg} para Egipto), el correo electrónico de su cuenta de Seller Center y la clave — después ejecute {test}.',
'Jumia_Guide_3' => 'Asegúrese de que el {sellerSku} de cada anuncio de Jumia sea igual al código del producto en Stocky — es el identificador que se usa tanto para enviar stock como para asociar pedidos.',
'Jumia_Guide_4' => 'Envíe precios y stock después de cada cambio de inventario; obtenga los pedidos con regularidad (Jumia no tiene webhooks en esta API).',
'Jumia_Guide_5' => 'La creación de anuncios nuevos se sigue haciendo en Seller Center — Jumia exige atributos específicos por categoría y una revisión de imágenes que solo su portal gestiona bien.',
'Mc_Hero_Title' => 'Sincronización de audiencia de Mailchimp',
'Mc_Hero_Desc' => 'Mantenga una audiencia de Mailchimp llena con sus clientes para poder lanzar campañas de correo electrónico sobre su base real de clientes.',
'Mc_Account_Audience' => 'Cuenta y audiencia',
'Mc_Api_Key_Placeholder' => 'p. ej., a1b2c3…-us14 (Account → Extras → API keys)',
'Mc_Audience' => 'Audiencia',
'Mc_N_Members' => '({n} miembros)',
'Mc_Load_Audiences_To_Pick' => 'Cargue las audiencias para elegir una',
'Mc_Load_Audiences' => 'Cargar audiencias',
'Mc_Double_Opt_In_Label' => 'Doble opt-in — los nuevos miembros reciben un correo de confirmación antes de unirse',
'Mc_Recommended_GDPR' => '(recomendado para el RGPD)',
'Mc_Auto_Sync_New' => 'Sincronizar automáticamente los nuevos clientes a medida que se crean',
'Mc_With_Email' => 'Con correo electrónico',
'Mc_Push_Desc' => 'Crea o actualiza en la audiencia seleccionada cada cliente que tenga dirección de correo electrónico (incluidos nombre y teléfono). Los miembros existentes conservan su estado de suscripción — nadie que se haya dado de baja vuelve a suscribirse. Los clientes sin correo electrónico quedan fuera.',
'Mc_Double_Opt_In_Off' => 'El doble opt-in está desactivado',
'Mc_Double_Opt_In_Off_Desc' => 'Los nuevos miembros se añadirán como suscritos sin correo de confirmación. Hágalo solo con clientes que ya aceptaron recibir marketing.',
'Mc_Guide_1' => 'En Mailchimp, abra {path} y cree una clave (termina en {suffix} — ese sufijo es su centro de datos).',
'Mc_Guide_2' => 'Pegue aquí la clave, guarde, haga clic en {load} y elija la audiencia que desea llenar.',
'Mc_Guide_3' => 'Deje activado el {doi}, salvo que sus clientes ya hayan dado su consentimiento para recibir correos de marketing.',
'Mc_Double_Opt_In_Lower' => 'doble opt-in',
'Mc_Guide_4' => 'Ejecute {push} para la carga inicial; active la {autoSync} para que los nuevos clientes se unan automáticamente.',
'Mc_Auto_Sync_Lower' => 'sincronización automática',
'Mc_Consent_Matters' => 'El consentimiento importa',
'Mc_Consent_Desc' => 'Enviar correos a personas que nunca aceptaron recibir marketing puede infringir el RGPD o la ley CAN-SPAM y provocar la suspensión de su cuenta de Mailchimp. El doble opt-in traslada la confirmación a Mailchimp — la opción segura por defecto.',
'Mc_No_Audiences' => 'No se encontraron audiencias en esta cuenta.',
'Presta_Hero_Desc' => 'Sincronice productos, stock y pedidos con su tienda PrestaShop a través de su API de webservice.',
'Presta_Webservice_Key' => 'Clave de webservice',
'Presta_Key_Placeholder' => 'En Advanced Parameters → Webservice',
'Presta_Key_Help' => 'Active el webservice en PrestaShop (Advanced Parameters → Webservice), cree una clave con permisos sobre products, stock_availables, orders y customers, y péguela aquí. Se almacena en modo de solo escritura.',
'Presta_Shop_Language_ID' => 'ID de idioma de la tienda',
'Presta_Language_Help' => 'ID de idioma que se usa para los nombres de producto al enviar (1 = el primer idioma de la tienda).',
'Presta_Push_Desc' => 'Crea en PrestaShop los productos simples que faltan (con su stock actual). Los productos ya vinculados y los productos con variantes se omiten — siga editando los detalles del producto en PrestaShop, u obténgalos para actualizar la copia local.',
'Presta_Pull_Desc' => 'Importa los productos de PrestaShop, asociando los existentes por referencia (SKU) y creando el resto. Las combinaciones se importan como su producto principal.',
'Presta_Reset_Confirm' => '¿Restablecer los vínculos de productos? El historial de pedidos conserva sus vínculos.',
'Presta_Stock_Desc' => 'Actualiza el stock de la tienda (stock_availables) de cada producto vinculado.',
'Presta_Orders_Desc' => 'Importa los pedidos de la tienda como ventas (referencias como {ref}), empezando por los más recientes. Los pedidos ya importados y los cancelados se omiten, así que es seguro obtenerlos con regularidad. PrestaShop no tiene webhooks — ejecútelo después de los periodos de mucha actividad.',
'Presta_Guide_1' => 'En el back office de PrestaShop, abra {path} y active el webservice.',
'Presta_Guide_2' => 'Añada una nueva clave con permiso {vae} sobre {products} y {stock}, y {view} sobre {orders} y {customers}.',
'Presta_Guide_3' => 'Pegue la URL de la tienda y la clave en la pestaña Conexión, guarde y ejecute {test}.',
'Presta_Guide_4' => 'Obtenga primero los productos si la tienda ya tiene un catálogo (se asocian por referencia/SKU); envíe para crear los productos simples que falten.',
'Presta_Guide_5' => 'Envíe el stock cada vez que cambien las cantidades y obtenga los pedidos con regularidad — PrestaShop no tiene webhooks, así que los pedidos solo llegan cuando los obtiene.',
'Presta_Identity_Title' => 'La identidad del producto es la referencia (SKU)',
'Presta_Identity_Desc' => 'El código de producto de Stocky se asocia con la referencia de PrestaShop. Mantenga las referencias coherentes en ambos lados; las combinaciones (variantes) se asocian en los pedidos por referencia, pero no se envían en esta versión.',
'Gs_Hero_Title' => 'Exportaciones a Google Sheets',
'Gs_Hero_Desc' => 'Exporte sus ventas, productos y clientes a una hoja de cálculo de Google en vivo — una pestaña para cada uno, actualizada a petición.',
'Gs_OAuth_Credentials' => 'Credenciales OAuth de Google',
'Gs_Secret_Placeholder' => 'De su cliente OAuth de Google Cloud',
'Gs_Auto_Export_Nightly' => 'Exportar automáticamente cada noche',
'Gs_Auto_Export_Hint' => '(todas las pestañas se actualizan hacia las 02:30, hora del servidor)',
'Gs_Enable_Exports' => 'Activar las exportaciones a Google Sheets',
'Gs_Account_Spreadsheet' => 'Cuenta y hoja de cálculo',
'Gs_Connect' => 'Conectar cuenta de Google',
'Gs_Reconnect' => 'Volver a conectar la cuenta de Google',
'Gs_Disconnect_Confirm' => '¿Desconectar la cuenta de Google? Las exportaciones se detienen hasta que vuelva a conectarla.',
'Gs_Target_Spreadsheet' => 'Hoja de cálculo de destino (ID o URL completa)',
'Gs_Spreadsheet_Placeholder' => 'Pegue la URL de una hoja de cálculo, o cree una →',
'Gs_Create_New' => 'Crear nueva',
'Gs_Open_Spreadsheet' => 'Abrir la hoja de cálculo ↗',
'Gs_Last_Export' => 'Última exportación: {date}',
'Gs_Redirect_Uri_Title' => 'URI de redirección para el cliente OAuth de Google',
'Gs_Export_Desc' => 'Cada exportación reescribe su pestaña desde cero (encabezado + todas las filas), así que la hoja siempre es una instantánea completa y actual. Los conjuntos de datos grandes se envían por lotes — deje la página abierta hasta que el contador se detenga.',
'Gs_Export_Sales' => 'Exportar ventas',
'Gs_Export_Products' => 'Exportar productos',
'Gs_Export_Customers' => 'Exportar clientes',
'Gs_Job_Sales_Desc' => 'Todas las ventas con cliente, totales, estado de pago y almacén.',
'Gs_Job_Products_Desc' => 'El catálogo completo con precios, costos y cantidades de stock actuales.',
'Gs_Job_Customers_Desc' => 'Todos los clientes con sus datos de contacto.',
'Gs_Guide_1' => 'Cree un proyecto en {console} y habilite la {api} (APIs & Services → Library).',
'Gs_Guide_2' => 'Configure la {consent} (External). Mientras permanezca en "Testing", añada su cuenta de Google como usuario de prueba — tenga en cuenta que los tokens de actualización en modo de prueba caducan a los 7 días, así que {publish} la aplicación para una conexión permanente.',
'Gs_OAuth_Consent_Screen' => 'OAuth consent screen',
'Gs_Publish' => 'publique',
'Gs_Guide_3' => 'Cree un {clientId} de tipo Web application y registre el URI de redirección que se muestra en la pestaña Conexión.',
'Gs_OAuth_Client_ID' => 'OAuth client ID',
'Gs_Guide_4' => 'Pegue aquí el Client ID y el Secret, guarde y haga clic en {connect}.',
'Gs_Guide_5' => 'Cree una hoja de cálculo con el botón (o pegue la URL de una que su cuenta de Google pueda editar) y luego ejecute las exportaciones.',
'Gs_Snapshots_Title' => 'Instantáneas, no sincronización en vivo',
'Gs_Snapshots_Desc' => 'Las exportaciones reescriben a petición las pestañas Sales / Products / Customers. Para actualizaciones en vivo fila por fila en cada venta, conecte Zapier — puede añadir filas en el momento en que se producen los eventos.',
'Gs_Connected_Spreadsheet' => 'Conectado — hoja de cálculo: {title}',
'Gs_Spreadsheet_Created' => 'Hoja de cálculo creada.',
'Gs_Account_Connected' => 'Cuenta de Google conectada.',
'Xero_Hero_Title' => 'Sincronización contable con Xero',
'Xero_Hero_Desc' => 'Envíe sus clientes como contactos de Xero y sus ventas como facturas — con los pagos, cuando hay una cuenta bancaria configurada.',
'Xero_App_Credentials_Accounts' => 'Credenciales de la aplicación y cuentas',
'Xero_From_Your_App' => 'De su aplicación en developer.xero.com',
'Xero_Sales_Account_Code' => 'Código de la cuenta de ventas',
'Xero_Sales_Account_Help' => 'Cuenta de ingresos para las líneas de factura (\'200\' es la cuenta de ventas (Sales) predeterminada de Xero).',
'Xero_Payment_Account_Code' => 'Código de la cuenta de pagos (opcional)',
'Xero_Payment_Code_Placeholder' => 'p. ej., 090',
'Xero_Payment_Account_Help' => 'Un código de cuenta bancaria. Si se indica, las ventas pagadas también registran un pago en la factura; déjelo vacío para sincronizar solo las facturas.',
'Xero_Auto_Sync' => 'Sincronizar automáticamente las nuevas ventas como facturas',
'Xero_Auto_Sync_Hint' => '(se ponen en cola en segundo plano a medida que se crean las ventas)',
'Xero_Org_Connection' => 'Conexión con la organización',
'Xero_Organisation' => 'Organización',
'Xero_Disconnect_Confirm' => '¿Desconectar la organización de Xero? La sincronización se detiene hasta que vuelva a conectarla.',
'Xero_Redirect_Uri_Title' => 'URI de redirección para la aplicación de Xero',
'Xero_Redirect_Help' => 'Cree una "Web app" en {link} y registre este URI de redirección. Nota: los tokens de acceso de Xero se renuevan automáticamente, pero una conexión inactiva durante más de 60 días debe volver a conectarse.',
'Xero_Contacts_In_Xero' => 'Contactos en Xero',
'Xero_Invoices_In_Xero' => 'Facturas en Xero',
'Xero_Payments_Recorded' => 'Pagos registrados',
'Xero_Push_Customers_Desc' => 'Crea o actualiza un contacto de Xero para cada cliente. Un cliente cuyo nombre ya existe en Xero se vincula a ese contacto.',
'Xero_Push_Sales_As_Invoices' => 'Enviar ventas como facturas',
'Xero_Push_Invoices_Desc' => 'Crea una factura AUTHORISED por venta (número de factura = la Ref. de la venta), con las líneas de artículos de la venta más las líneas de envío, descuento e impuesto, para que el total en Xero coincida con el total de la venta. Las ventas que ya están en Xero se omiten — las facturas nunca se editan. Los contactos que faltan se crean sobre la marcha.',
'Xero_Push_Invoices' => 'Enviar facturas',
'Xero_Reset_Contact_Confirm' => '¿Restablecer los vínculos de contactos? El próximo envío los volverá a vincular o a crear.',
'Xero_Reset_Contact_Links' => 'Restablecer vínculos de contactos',
'Xero_Guide_1' => 'Cree una {webApp} en {link} (My Apps → New app).',
'Xero_Web_App' => 'Web app',
'Xero_Guide_2' => 'Registre el URI de redirección que se muestra en la pestaña Conexión.',
'Xero_Guide_3' => 'Copie el {clientId} de la aplicación y genere un {clientSecret}; pegue ambos aquí y guarde.',
'Xero_Guide_4' => 'Haga clic en {connect}, inicie sesión y elija la organización que desea conectar.',
'Xero_Guide_5' => 'Revise los códigos de cuenta: la cuenta de ventas recibe las líneas de factura; indique un código de cuenta bancaria si las ventas pagadas también deben registrar pagos.',
'Xero_Guide_6' => 'Envíe primero los clientes y después las facturas. Los números de factura son las Ref. de las ventas, así que Xero rechaza los duplicados aunque se restablezcan los vínculos.',
'Xero_Tax_Inclusive_Title' => 'Los importes se envían tal cual, con impuestos incluidos',
'Xero_Tax_Inclusive_Desc' => 'Las facturas usan líneas NoTax que reflejan exactamente la venta (artículos + envío − descuento + impuesto), por lo que los totales de Xero siempre coinciden con los de Stocky. Su contador puede reasignar las líneas de impuesto y envío a las cuentas adecuadas dentro de Xero.',
'Xero_Org_Connected' => 'Organización de Xero conectada.',
'Salla_Hero_Desc' => 'Sincronice productos, stock y pedidos con su tienda Salla — los pedidos llegan automáticamente mediante webhooks.',
'Salla_App_Credentials' => 'Credenciales de la aplicación',
'Salla_From_Partners_App' => 'Desde su app de Salla Partners',
'Salla_Webhook_Secret' => 'Secreto del webhook',
'Salla_Webhook_Secret_Placeholder' => 'Secreto de firma de la página Webhooks de su app',
'Salla_Token_Expires' => 'El token caduca',
'Salla_Disconnect_Confirm' => '¿Desconectar la tienda de Salla? La sincronización se detiene hasta que vuelva a conectarla.',
'Salla_Urls_Title' => 'URL para el portal de Salla Partners',
'Salla_OAuth_Callback' => 'Callback de OAuth',
'Salla_Webhook_Url_All' => 'URL del webhook (todos los eventos)',
'Salla_Urls_Help' => 'Configure ambas en su app en {link}, elija la estrategia de seguridad de webhook {signature} y suscríbase a los eventos de pedidos, productos y app.',
'Salla_Variants_Linked' => 'Variantes vinculadas',
'Salla_Push_Desc' => 'Crea o actualiza productos simples en Salla por SKU. Los productos con variantes se omiten en esta versión: impórtelos desde Salla o vincúlelos por SKU.',
'Salla_Only_Unlinked' => 'Solo productos aún no vinculados',
'Salla_Pull_Desc' => 'Importa los productos de Salla (variantes incluidas), vinculando los existentes por SKU y creando el resto.',
'Salla_Reset_Confirm' => '¿Restablecer los vínculos de productos y variantes? El historial de pedidos conserva sus vínculos.',
'Salla_Stock_Desc' => 'Envía las cantidades actuales de cada producto vinculado (por SKU) y de cada variante vinculada.',
'Salla_Orders_Desc' => 'Los nuevos pedidos de Salla normalmente llegan solos a través de webhooks y se convierten en ventas. Use esta importación para recuperar los pedidos realizados antes de configurar el webhook; los pedidos ya importados se omiten.',
'Salla_Guide_1' => 'Cree una app (privada) en {link} y elija el flujo de autorización {mode}.',
'Salla_Guide_2' => 'Copie el {clientId} y el {clientSecret} de la app en la pestaña Conexión y guarde.',
'Salla_Guide_3' => 'En la configuración de la app, establezca la URL de callback de OAuth que se muestra en la pestaña Conexión.',
'Salla_Guide_4' => 'En la página Webhooks de la app: elija la estrategia de seguridad {signature}, copie su secreto en el campo Secreto del webhook de aquí, establezca la URL del webhook que se muestra en la pestaña Conexión y suscríbase como mínimo a {e1}, {e2}, {e3}, {e4}, {e5} y {e6}.',
'Salla_Guide_5' => 'Haga clic en {connect} y apruebe la app en su tienda. (Las apps en Easy Mode se conectan automáticamente mediante el webhook {webhook}).',
'Salla_Guide_6' => 'Importe o exporte productos y luego envíe el stock. Los nuevos pedidos llegan automáticamente y aparecen en Ventas con referencias como {ref}.',
'Salla_Identity_Title' => 'La identidad del producto es el SKU',
'Salla_Identity_Desc' => 'El código de producto de Stocky se vincula con el SKU de Salla. Mantenga los SKU coherentes en ambos lados; los productos con variantes se vinculan al importar y en los pedidos, pero no se exportan en esta versión.',
'Salla_Store_Connected' => 'Tienda de Salla conectada.',

