'Fbr_Page_Title' => 'Facturación digital FBR (Pakistán)',
'Fbr_Token_Saved' => 'Hay un token guardado (••••{last4}). Déjelo en blanco para conservarlo.',
'Fbr_Token_Obtain' => 'Obtenga el token en el portal de facturación electrónica PRAL / IRIS.',
'Fbr_Token_Placeholder' => 'Pegue el token del portal de facturación electrónica PRAL / IRIS',
'Fbr_Guide_What_Title' => '¿Qué es la facturación digital de FBR?',
'Fbr_Guide_What_Body' => 'Según la SRO 69(I)/2025, la Federal Board of Revenue (Pakistán) exige a las empresas integradas declarar electrónicamente sus facturas de venta en tiempo real a través de la API de PRAL Digital Invoicing (DI). Cada venta aceptada recibe un número de factura FBR oficial, y los recibos deben mostrar ese número junto con un código QR de verificación.',
'Fbr_Guide_Steps_Title' => 'Pasos para entrar en producción',
'Fbr_Guide_Step_1' => 'Regístrese en el portal de facturación electrónica IRIS de FBR y obtenga un token de seguridad de {sandbox}.',
'Fbr_Guide_Step_2' => 'Configure su perfil de vendedor en la pestaña Configuración (NTN/CNIC, nombre comercial, provincia, dirección), pegue el token y habilite la integración con el entorno establecido en {sandbox}.',
'Fbr_Guide_Step_3' => 'Realice ventas de prueba que cubran los escenarios que FBR le asignó (elija el escenario en el campo Escenario de sandbox). Revise la pestaña Documentos para confirmar que vuelven como {valid}.',
'Fbr_Guide_Step_4' => 'Cuando FBR apruebe sus pruebas en sandbox, obtenga el token de {production} en el portal, péguelo aquí y cambie el entorno a {production}.',
'Fbr_Guide_Step_5' => 'Los recibos muestran automáticamente el número de factura FBR y el código QR una vez aceptada la venta; no se necesitan pasos adicionales en el punto de venta.',
'Fbr_Sandbox_Lower' => 'sandbox',
'Fbr_Production_Lower' => 'producción',
'Fbr_Guide_Note_1' => 'Configure los códigos HS de cada producto en el formulario del producto (campo "Código HS"). El código HS predeterminado configurado aquí solo se usa para los productos que no tienen uno.',
'Fbr_Guide_Note_2' => 'Los clientes ocasionales no registrados se declaran a FBR como "Unregistered".',
'Fbr_Guide_Note_3' => 'Los compradores registrados deben tener su NTN en el campo Número de identificación fiscal del cliente para que se declaren como registrados.',
'Fbr_Guide_Note_4' => 'Los envíos fallidos o no válidos se pueden reintentar desde la pestaña Documentos tras corregir la causa; la pestaña Registros muestra los intercambios sin procesar con la API para solucionar problemas.',
