'Woo_WordPress_App_Password' => 'Contraseña de aplicación de WordPress',
'Woo_Automatic_Sync' => 'Sincronización automática',
'Woo_Auto_Sync_Intro' => 'Envía a WooCommerce los cambios hechos en Stocky en el momento en que ocurren, sin abrir esta página. Cada envío se ejecuta justo después de guardar la acción, así que el cajero nunca espera a WooCommerce. Los resultados aparecen en la pestaña Registros.',
'Woo_Auto_Sync_Products_Help' => 'Un producto creado, editado o duplicado en Stocky se envía a WooCommerce (detalles, precio, variantes, imágenes, stock). Las importaciones masivas no se envían; tras una importación, use Sincronizar — POS → WooCommerce en la pestaña Productos.',
'Woo_Auto_Sync_Stock_Help' => 'Cualquier movimiento de stock (venta POS, venta, devolución, compra, ajuste, transferencia) actualiza en WooCommerce la cantidad de los productos implicados. Solo se actualizan los productos ya vinculados a WooCommerce.',
'Woo_Sync_Tuning' => 'Ajuste de la sincronización',
'Woo_Sync_Tuning_Intro' => 'Los valores predeterminados sirven para la mayoría de las tiendas. Cámbielos solo si la sincronización es lenta o agota el tiempo de espera en su hosting. Cada valor está limitado a un rango seguro, y vaciar un campo restaura su valor predeterminado.',
'Woo_Sync_Guide' => 'Guía de sincronización de WooCommerce',
'Woo_Guide_Getting_Keys' => 'Obtener las claves de API',
'Woo_Guide_Keys_1' => 'En WooCommerce: WooCommerce → Settings → Advanced → REST API.',
'Woo_Guide_Keys_2' => 'Haga clic en Add key, elija Read/Write y copie la Consumer key y el Consumer secret.',
'Woo_Guide_Keys_3' => 'URL de la tienda: la URL de su sitio sin barra final (p. ej., {example}).',
'Woo_Guide_WP_Title' => 'Usuario de WP y Application Password (opcional)',
'Woo_Guide_WP_Intro' => 'Estos campos solo se usan para las imágenes de productos. La API de WooCommerce (URL de la tienda + Consumer key/secret) se encarga de sincronizar productos, stock, categorías, marcas, clientes y pedidos; la API REST de WordPress gestiona la biblioteca de medios (buscar y subir imágenes).',
'Woo_Guide_WP_1' => 'Al sincronizar productos o stock, Stocky puede adjuntar imágenes de productos: primero busca una imagen existente por nombre de archivo en la biblioteca de medios de WordPress; si no la encuentra, sube la imagen mediante la API de WordPress.',
'Woo_Guide_WP_2' => 'Use un usuario de WordPress que pueda gestionar medios (p. ej., Administrator). Cree una Application Password en WordPress: Users → Profile (o su usuario) → Application Passwords; añada una nueva y péguela aquí.',
'Woo_Guide_WP_3' => 'Si deja estos campos en blanco, la sincronización sigue funcionando para todos los datos (productos, stock, categorías, marcas, clientes, pedidos); solo se omite la vinculación de imágenes de productos (búsqueda/subida).',
'Woo_Guide_How_To_Enable' => 'Cómo activarlo',
'Woo_Guide_Enable_1' => 'Introduzca arriba la URL de la tienda, la clave del consumidor y el secreto del consumidor, y haga clic en Guardar.',
'Woo_Guide_Enable_2' => 'Use Probar conexión para verificar las credenciales.',
'Woo_Guide_Enable_3' => 'Use la sincronización manual desde cualquier pestaña cuando necesite sincronizar.',
'Woo_Guide_Enable_4' => 'Active la Sincronización automática arriba para enviar a WooCommerce los productos nuevos y editados, y cada cambio de stock, en el momento en que se produzcan.',
'Woo_Guide_Manual_Sync' => 'Sincronización manual (a demanda)',
'Woo_Guide_Manual_1' => 'La sincronización funciona en ambas direcciones: Stocky → WooCommerce y WooCommerce → Stocky.',
'Woo_Guide_Manual_2' => 'La sincronización manual está disponible en todas las pestañas de WooCommerce (Productos, Stock, etc.); use las acciones de sincronización de cada pestaña para sincronizar a demanda.',
'Woo_Guide_Auto_1' => 'Productos: si está activada, un producto que cree, edite o duplique en Stocky se envía a WooCommerce justo después de guardarlo, seguido de su stock.',
'Woo_Guide_Auto_2' => 'Stock: si está activada, cada cambio de stock (venta POS, venta, devolución, compra, ajuste, transferencia) actualiza la cantidad en WooCommerce. Solo se actualizan los productos ya vinculados a WooCommerce.',
'Woo_Guide_Auto_3' => 'La sincronización automática solo envía cambios de Stocky a WooCommerce. La importación de datos de WooCommerce a Stocky (pedidos, clientes, productos) siempre se hace con los botones de las pestañas Pedidos, Clientes y Productos.',
'Woo_Guide_Auto_4' => 'Las importaciones masivas de productos no se envían automáticamente. Después de una importación, use Sincronizar — POS → WooCommerce en la pestaña Productos.',
'Woo_Guide_Auto_5' => 'Cada envío automático queda registrado en la pestaña Registros, para que pueda comprobar qué se envió y detectar errores.',
'Woo_Guide_First_Setup' => 'Configuración inicial',
'Woo_Guide_First_1' => 'Ejecute estas acciones una vez, en este orden, para vincular su catálogo existente: Sincronizar — POS → WooCommerce en la pestaña Categorías, luego en la pestaña Marca, luego en la pestaña Productos y, por último, Sincronizar stock en la pestaña Stock. Después, active la Sincronización automática arriba para mantener WooCommerce actualizado.',
'Woo_Guide_First_2' => 'Las sincronizaciones grandes de productos y stock se ejecutan en lotes pequeños y muestran su progreso en la pestaña. Mantenga la página abierta hasta que termine la sincronización; puede detenerla en cualquier momento.',
'Woo_Guide_First_3' => 'Si una sincronización deja de avanzar durante varios minutos, revise la pestaña Registros y luego contacte con soporte.',
'Woo_Guide_Notes_1' => 'Cambiar la URL de la tienda o las claves de API restablece las asignaciones (productos, categorías, marcas, clientes); los elementos se sincronizarán de nuevo con la (nueva) tienda.',
'Woo_Guide_Notes_2' => 'Mantenga los SKU coherentes entre Stocky y WooCommerce para evitar productos duplicados y volver a vincularlos de forma segura.',
