'Pg_Sandbox_Test_Mode' => 'Sandbox (modo de prueba)',
'Pg_Stripe_Shared_Notice' => 'Las claves de Stripe son compartidas por todo el sistema.',
'Pg_Store_Feature_Not_In_Plan' => 'Las pasarelas de la tienda online y los métodos de pago sin conexión forman parte de la función Pedidos en línea, que su plan actual no incluye.',
'Pg_Intro_Title' => 'Cada pasarela de esta página se ofrece en el pago de la TIENDA ONLINE una vez que sus credenciales están guardadas y su interruptor está activado.',
'Pg_Intro_Desc' => 'Cada pestaña tiene su propio interruptor de activación, que se guarda en cuanto lo cambia: desactivar una pasarela conserva sus credenciales; el pago simplemente deja de ofrecerla. Las claves de Stripe se comparten globalmente (el panel de administración y la tienda online usan la misma integración de Stripe). Pagos sin conexión incluye el pago contra entrega y el dinero móvil, que se pagan fuera del sistema.',
'Pg_Label_Stripe_Key' => 'CLAVE DE STRIPE',
'Pg_Label_Stripe_Secret' => 'SECRETO DE STRIPE',
'Pg_Card_Payments_Off' => 'Los pagos con tarjeta están desactivados',
'Pg_Card_Keys_Kept' => 'Sus claves se conservan: el pago de la tienda online simplemente deja de ofrecer la opción de tarjeta hasta que la vuelva a activar.',
'Pg_No_Stripe_Key' => 'No hay ninguna clave de Stripe guardada',
'Pg_Enter_Stripe_Key' => 'Introduzca su clave y su secreto de Stripe para empezar a aceptar pagos con tarjeta en la tienda online.',
'Pg_Label_Razorpay_Key_Id' => 'RAZORPAY KEY ID',
'Pg_Label_Razorpay_Key_Secret' => 'RAZORPAY KEY SECRET',
'Pg_Razorpay_Help' => 'Usa Razorpay Checkout en la tienda (tarjetas, UPI, banca en línea, monederos). El modo de prueba o producción lo decide el par de claves (rzp_test_/rzp_live_); no hay un interruptor de sandbox aparte. El pago ofrece Razorpay en cuanto ambas claves están guardadas.',
'Pg_Label_Bkash_App_Key' => 'BKASH APP KEY',
