'Pg_Label_Bkash_Username' => 'USUARIO DE BKASH',
'Pg_Label_Bkash_Password' => 'CONTRASEÑA DE BKASH',
'Pg_Bkash_Sandbox_Help' => 'ACTIVADO usa tokenized.sandbox.bka.sh con sus credenciales de sandbox; desactívelo para cobrar a cuentas reales de bKash en tokenized.pay.bka.sh.',
'Pg_Bkash_Help' => 'Usa bKash Tokenized Checkout (credenciales de comerciante del portal de comerciantes de bKash). Cobra en BDT. El pago ofrece bKash en cuanto las cuatro credenciales están guardadas.',
'Pg_Label_Sslcommerz_Store_Id' => 'SSLCOMMERZ STORE ID',
'Pg_Label_Sslcommerz_Store_Password' => 'SSLCOMMERZ STORE PASSWORD',
'Pg_Sslcommerz_Sandbox_Help' => 'ACTIVADO usa sandbox.sslcommerz.com con credenciales de sandbox; desactívelo para cobrar a clientes reales en securepay.sslcommerz.com.',
'Pg_Sslcommerz_Help' => 'Pago alojado que admite tarjetas, banca móvil bKash/Nagad/Rocket y banca por internet en Bangladés. Cobra en BDT.',
'Pg_Sslcommerz_Ipn_Help' => 'URL de IPN (respaldo recomendado; configúrela en My Stores → IPN Settings del panel de comerciante de SSLCommerz):',
'Pg_Label_Region' => 'REGIÓN',
'Pg_Paymob_Region_Help' => 'País de su cuenta de Paymob: egypt, ksa, uae, pakistan u oman (selecciona el host de la API; por defecto, egypt).',
'Pg_Label_Public_Key' => 'CLAVE PÚBLICA',
'Pg_Label_Secret_Key' => 'CLAVE SECRETA',
'Pg_Label_Api_Key' => 'CLAVE DE API',
'Pg_Label_Integration_Ids' => 'ID DE INTEGRACIÓN',
'Pg_Paymob_Integration_Help' => 'Desde Paymob Dashboard → Developers → Payment Integrations; separe varios con comas para ofrecer varios métodos.',
'Pg_Paymob_Integration_Placeholder' => 'p. ej., 4419544 o 4419544,4419545',
'Pg_Label_Hmac_Secret' => 'SECRETO HMAC',
'Pg_Label_Charge_Currency' => 'MONEDA DE COBRO',
'Pg_Paymob_Currency_Help' => 'Debe coincidir con la moneda de su cuenta de Paymob (EGP, SAR, AED, PKR u OMR) y con la moneda base de su tienda.',
'Pg_Paymob_Help' => 'Usa Paymob Unified Checkout (tarjetas, monederos y métodos locales en Egipto, Arabia Saudí, EAU, Pakistán y Omán). Las cinco credenciales se obtienen en Paymob Dashboard → Settings → Account Info + Payment Integrations.',
'Pg_Paymob_Webhook_Help' => 'El webhook se configura automáticamente en cada pago; no hace falta configurar nada en el panel. URL de devolución de llamada de respaldo, como referencia:',
'Pg_Label_Api_Token' => 'TOKEN DE API',
'Pg_Label_Account_Country_Live' => 'PAÍS DE LA CUENTA (PRODUCCIÓN)',
'Pg_Myfatoorah_Country_Help' => 'Código ISO del país de su cuenta de MyFatoorah: KWT, SAU, QAT, EGY, ARE, BHR, OMN o JOR. Selecciona el host de la API de producción; se ignora en modo sandbox.',
'Pg_Myfatoorah_Currency_Help' => 'Debe coincidir con la moneda de su cuenta de MyFatoorah (KWD, SAR, AED, QAR, BHD, OMR, JOD, EGP…) y con la moneda base de su tienda.',
'Pg_Myfatoorah_Sandbox_Help' => 'ACTIVADO usa apitest.myfatoorah.com con un token de API de demostración; desactívelo para cobrar a clientes reales en la API de producción.',
'Pg_Myfatoorah_Help' => 'Enlace de factura alojado que admite KNET, mada, tarjetas, Apple Pay y STC Pay en todo el CCG. El token de API se obtiene en MyFatoorah Vendor Portal → Integration Settings → API Key.',
'Pg_Moyasar_Currency_Help' => 'SAR por defecto; debe coincidir con la moneda base de su tienda.',
'Pg_Moyasar_Help' => 'Página de factura alojada que admite mada, tarjetas de crédito, Apple Pay y STC Pay en Arabia Saudí. Use una clave sk_test_ para el sandbox; Moyasar no tiene un host de prueba aparte.',
'Pg_Label_Account_Id' => 'ID DE CUENTA',
'Pg_Xpay_Account_Help' => 'XPay Dashboard > Settings > Store Info.',
'Pg_Xpay_Account_Placeholder' => 'Su ID de cuenta de XPay',
'Pg_Label_Publishable_Key' => 'CLAVE PUBLICABLE',
'Pg_Xpay_Publishable_Help' => 'Settings > Store Info > Key Details > API Keys; la usa el elemento de tarjeta en el navegador.',
'Pg_Label_Api_Hmac_Secret' => 'SECRETO HMAC DE API',
'Pg_Xpay_Hmac_Placeholder' => 'Key Details > HMAC Keys',
'Pg_Label_Webhook_Hmac_Secret' => 'SECRETO HMAC DEL WEBHOOK',
'Pg_Label_Webhook_Url' => 'URL DEL WEBHOOK',
'Pg_Xpay_Webhook_Help' => 'Pegue esta URL en XPay Dashboard > Settings > Store Info > Webhook URL.',
'Pg_Xpay_Currency_Help' => 'PKR; debe coincidir con la moneda base de su tienda.',
'Pg_Xpay_Sandbox_Help' => 'ACTIVADO usa xstak-pay-stg.xstak.com con sus claves de staging; desactívelo (y guarde sus claves de producción) para cobrar a clientes reales.',
'Pg_Xpay_Help' => 'Las tarjetas se introducen en un elemento de XPay integrado en la página de pago (sin redirección). Cada pago se vuelve a verificar en el servidor antes de crear el pedido. Nota: el SDK de XPay requiere el secreto HMAC de API en el navegador, igual que los plugins oficiales de XPay.',
'Pg_Label_Payfast_Merchant_Id' => 'PAYFAST MERCHANT ID',
