'Shp_Where_Data_Lands' => 'Destino de los datos',
'Shp_What_To_Sync' => 'Qué sincronizar',
'Shp_Name_Hint' => 'Cómo se identifica esta tienda en el ERP',
'Shp_Name_Placeholder' => 'p. ej., Tienda principal',
'Shp_Domain_Hint' => '{domain}; también sirve la URL del panel de administración',
'Shp_App_Credentials' => 'Credenciales de la app',
'Shp_Auth_Client_Credentials' => 'Client ID + client secret (app de Dev Dashboard)',
'Shp_Auth_Token' => 'Token de acceso de Admin API (app personalizada heredada)',
'Shp_Cc_Alert' => 'Desde enero de 2026, Shopify ya no crea apps personalizadas en el panel de administración. Cree la app en el {dashboard}, concédale los permisos (scopes) de Admin API, instálela en esta tienda y luego copie el Client ID y el Client secret desde su página {settings}. El ERP obtiene por sí mismo un token de acceso nuevo cada 24 horas. La app y la tienda deben pertenecer a la misma organización de Shopify.',
'Shp_Leave_Blank_Keep_Stored' => 'Déjelo en blanco para conservar el valor guardado.',
'Shp_Client_Id_Placeholder' => 'Desde la página Settings de la app',
'Shp_Client_Secret_Hint' => 'También firma los webhooks, así que no hace falta un secreto de firma aparte.',
'Shp_Masked_Unchanged' => '•••••••••••••• (sin cambios)',
'Shp_Token_Keep_Hint' => 'Déjelo en blanco para conservar el token ya guardado.',
'Shp_Token_Legacy_Hint' => 'Solo para apps personalizadas creadas en el panel de administración de Shopify antes de 2026 (Apps → Develop apps → API credentials). Las apps nuevas no muestran un token; use en su lugar el Client ID + secret.',
'Shp_Webhook_Signing_Secret' => 'Secreto de firma del webhook',
'Shp_Webhook_Secret_Optional_Hint' => 'Opcional aquí: el secreto de cliente indicado arriba firma los webhooks de una app de Dev Dashboard.',
'Shp_Webhook_Secret_Required_Hint' => 'Obligatorio para que se acepten los webhooks; las entregas sin firma se rechazan.',
'Shp_Will_Be_Cleared' => 'Se borrará al guardar',
'Shp_Clear_Stored_Secret' => 'Borrar el secreto guardado',
'Shp_Keep_It' => 'Conservarlo',
'Shp_Domain_Locked' => 'El dominio está bloqueado porque cambiarlo invalida todas las asignaciones de esta tienda.',
'Shp_Change_Anyway' => 'Cambiarlo de todos modos',
'Shp_Domain_Change_Warning' => 'Guardar un dominio diferente elimina todas las asignaciones de registros de esta conexión: los ID guardados pertenecen a la tienda anterior.',
'Shp_ERP_Warehouse' => 'Almacén del ERP',
'Shp_ERP_Warehouse_Hint' => 'Los niveles de stock y los pedidos importados pertenecen a este almacén.',
'Shp_Available_After_Connecting' => 'Disponible después de conectar',
'Shp_Fetch_Locations' => 'Obtener ubicaciones de Shopify',
'Shp_Price_Sent' => 'Precio enviado a Shopify',
'Shp_Create_Missing_Products' => 'Crear productos en el ERP para los productos de Shopify que no coincidan con un SKU',
'Shp_Create_Missing_Customers' => 'Crear clientes en el ERP para los clientes de Shopify que no coincidan con un correo electrónico',
'Shp_Create_Missing_Customers_Hint' => 'Si está desactivado, un pedido de un cliente desconocido se omite en lugar de asignarse al azar.',
'Shp_Entities_Lead' => 'Solo se pueden sincronizar las entidades activadas aquí: una tienda de la que solo obtiene pedidos no debería recibir un envío de productos accidental que reescriba su catálogo.',
'Shp_Sync_On_Schedule' => 'Sincronizar automáticamente según una programación',
'Shp_Scheduler_Hint' => 'El programador comprueba cada 5 minutos, que es la frecuencia más fina que pueden usar los intervalos siguientes. Las sincronizaciones siempre se pueden iniciar manualmente.',
'Shp_Instant_Push_Hint' => 'Una venta, devolución o ajuste envía el stock solo de esos productos en el instante en que se guarda, así que la tienda queda al día en segundos en lugar de en la siguiente ejecución programada. No hay nada más que instalar: el envío se ejecuta después de responder a la venta, así que la caja nunca espera a Shopify.',
'Shp_Switch_Inventory_First' => 'Active primero Inventario en {tab}.',
'Shp_Leave_Off_Lag' => 'Si lo deja desactivado, una venta POS solo llega a Shopify en el siguiente envío de inventario, hasta {n} minutos después.',
'Shp_Default_Interval' => 'Intervalo predeterminado (minutos)',
'Shp_Default_Interval_Hint' => 'Lo usan todos los pasos que no definen el suyo.',
'Shp_What_Runs_Auto' => 'Qué se ejecuta automáticamente',
'Shp_Plan_Hint' => 'Cada paso es una entidad en una dirección. Los pedidos solo llegan {from} Shopify.',
'Shp_From' => 'desde',
'Shp_Add_Step' => 'Añadir paso',
'Shp_Using_Default_Plan' => 'Usando el plan predeterminado',
'Shp_Default_Plan_Desc' => 'Los pedidos se obtienen y el stock se envía cada {n} minutos. Añada un paso para definir el suyo; si vuelve a vaciar la lista, se restaura este valor predeterminado.',
'Shp_N_Min' => '{n} min',
'Shp_Step_Entity_Off' => '{entity} está desactivado en la pestaña anterior; este paso se omitirá.',
'Shp_Inactive_Lc' => 'inactivo',
'Shp_No_Locations' => 'Esa tienda no tiene ninguna ubicación',
'Shp_Could_Not_Load_Locations' => 'No se pudieron cargar las ubicaciones; compruebe primero la conexión',
'Shp_Store_Updated' => 'Tienda actualizada',
'Shp_Store_Connected' => 'Tienda conectada',
'Shp_Could_Not_Save_Store' => 'No se pudo guardar esta tienda',
'Shp_G_Lead_Store' => 'Lo que necesita esta tienda para mantenerse sincronizada. Todo lo que aparece aquí es específico de esta tienda: la URL del webhook y los ID son reales.',
'Shp_G_Lead_Store_Cmd' => 'Lo que necesita esta tienda para mantenerse sincronizada. Todo lo que aparece aquí es específico de esta tienda: la URL del webhook y los ID son reales, así que los comandos se pueden copiar directamente en el servidor.',
'Shp_G_Lead_Generic' => 'Cómo se mantiene sincronizada una tienda de Shopify con el ERP. Elija una tienda arriba para ver su propio estado, o léalo tal cual: la URL del webhook es la misma sea cual sea la tienda que conecte.',
'Shp_G_Lead_Generic_Cron' => 'Cómo se mantiene sincronizada una tienda de Shopify con el ERP. Elija una tienda arriba para ver su propio estado, o léalo tal cual: la URL del webhook y la línea de cron son las mismas sea cual sea la tienda que conecte.',
'Shp_G_Ways_Note' => 'La mayoría de las tiendas usan ambas: la primera mantiene la tienda al día minuto a minuto y la segunda recoge lo que la primera haya pasado por alto: un webhook que nunca llegó, una edición hecha directamente en el panel de Shopify, una noche en que el sitio estuvo caído.',
'Shp_G_Both_Need' => 'Ambas formas necesitan esto primero',
'Shp_G_Credentials' => 'Credenciales de Shopify',
'Shp_G_Cred_Intro' => 'Desde enero de 2026, Shopify ya no crea apps personalizadas dentro del panel de administración, así que hay dos tipos de conexión:',
'Shp_G_Cred_Dev' => '{app} (cualquier tienda que se conecte ahora): {path}. Conceda los permisos de Admin API para lo que sincroniza esta tienda, instale la app en la tienda y luego copie el {clientId} y el {clientSecret} desde la página Settings de la app en {edit}. El ERP los intercambia por sí mismo por un token de acceso y lo renueva antes de que caduque, cada 24 horas. El secreto de cliente también firma los webhooks, así que no se necesita nada más. La app y la tienda deben estar en la misma organización de Shopify.',
'Shp_G_Dev_App' => 'App de Dev Dashboard',
'Shp_G_Cred_Legacy' => '{app} (creada en el panel de administración antes de 2026): sigue funcionando sin cambios con su {token} ({prefix}) y su {secret} como secreto de firma del webhook. No es el mismo valor que el token, y confundirlos es la razón habitual por la que se rechazan los webhooks.',
'Shp_G_Legacy_App' => 'App personalizada heredada',
'Shp_G_Api_Secret_Key' => 'API secret key',
'Shp_G_Stored' => 'guardado',
'Shp_G_Missing_Refused' => 'falta: las entregas se rechazarán',
'Shp_G_Targets' => '{path} El almacén del ERP cuyo stock vende esta tienda y la ubicación de Shopify donde se escribe ese stock. La sincronización de inventario y la importación de pedidos no se ejecutan sin ellos.',
'Shp_G_Currently' => 'Actualmente: almacén {warehouse}, ubicación {location}',
'Shp_G_Not_Set_Lc' => 'sin configurar',
'Shp_G_Ready' => 'listo',
'Shp_G_Incomplete' => 'incompleto',
'Shp_G_Manual_Syncs' => 'Sincronizaciones que inicia manualmente',
'Shp_G_Manual_Body' => 'Una sincronización iniciada desde el {centre} responde al instante y se ejecuta en segundo plano, en tramos cortos que continúan cada uno donde se detuvo el anterior. Un catálogo grande nunca queda cortado a medias por una solicitud web que agota su tiempo, y cerrar la página no la detiene.',
'Shp_G_Worker_Managed' => 'Su plataforma ejecuta el worker necesario, así que no hay nada que instalar.',
'Shp_G_Worker_Cron' => 'El worker necesario es una línea de cron más:',
'Shp_G_Cron_Copied' => 'Línea de cron copiada',
'Shp_G_Worker_Busy' => 'Si el worker está ocupado, la página abierta del Centro de sincronización continúa la ejecución por sí misma tras unos segundos, una solicitud corta cada vez, así que una sincronización siempre termina mientras usted la observa.',
'Shp_G_Pick_How' => 'Luego elija cómo se mantiene sincronizada',
'Shp_G_Right_Away' => 'Al instante',
'Shp_G_Stock_Live' => 'stock en tiempo real',
'Shp_G_Stock_Not_Live' => 'stock no en tiempo real',
'Shp_G_Realtime_Lead' => 'Cada cambio se envía en cuanto ocurre, en segundos. Son dos mitades con interruptores separados: los {webhooks} traen los eventos propios de la tienda y el {push} saca el stock hacia la tienda.',
'Shp_G_Webhooks_Lc' => 'webhooks',
'Shp_G_Instant_Push_Lc' => 'envío instantáneo de stock',
'Shp_G_Webhooks_Heading' => 'Webhooks — la tienda → el ERP',
'Shp_G_Webhooks_Body' => 'Pedidos, cambios de estado de pedidos y ediciones de productos, clientes y stock hechas en Shopify. Abra la tienda y pulse {button} en su {tab}; puede pulsarlo dos veces sin problema. Shopify envía a:',
'Shp_G_Webhooks_Tab' => 'pestaña Webhooks',
'Shp_G_Webhooks_Note' => 'La dirección debe ser accesible desde internet por HTTPS: Shopify no entrega a {localhost} ni a un dominio {test}. Cada entrega se registra una sola vez, así que los reintentos de Shopify no pueden crear un pedido duplicado, y una entrega fallida se puede reprocesar. Las entregas se rechazan hasta que se guarde el secreto de firma del paso 1.',
'Shp_G_Push_Heading' => 'Envío instantáneo de stock — el ERP → la tienda',
'Shp_G_People_Miss' => 'Este es el ajuste que la gente pasa por alto',
'Shp_G_Push_P1' => 'Una venta POS {not} llega a Shopify por sí sola. Si está desactivado, la tienda solo se entera en el siguiente paso de envío de inventario, y en ese intervalo puede vender una unidad que usted ya vendió en caja.',
'Shp_G_Not' => 'no',
'Shp_G_Push_P2' => 'Marque {setting} en {path}. Esa es toda la configuración: sin worker ni cron. Cada venta, devolución y ajuste envía entonces solo esos productos, justo después de guardar la venta, y una venta de veinte líneas cuesta un envío, no veinte. La caja nunca lo espera.',
'Shp_G_This_Store' => 'Esta tienda:',
'Shp_G_Push_On' => 'activado: stock enviado al cambiar',
'Shp_G_Push_Off' => 'desactivado: stock solo según la programación',
'Shp_G_Push_Note' => 'Solo se envían los productos que ya tienen una asignación en Shopify, y solo los movimientos del almacén de esta tienda. Las operaciones masivas (eliminar un producto, restablecer un almacén) escriben el stock sin generar un evento, lo cual es una razón para mantener también el paso de inventario programado.',
'Shp_G_Nothing_Else' => 'Nada más que instalar',
'Shp_G_Nothing_Else_Body' => 'Ninguna de las dos mitades necesita un worker de cola ni una entrada de cron. Un webhook entrante se procesa en la propia solicitud que hace Shopify; un envío de stock saliente se ejecuta en el mismo proceso que atendió la venta, {after} de que la respuesta se haya devuelto, así que la caja nunca espera a Shopify, y una tienda que deja de responder se abandona tras diez segundos y se deja para el siguiente envío de inventario programado.',
'Shp_G_After' => 'después',
'Shp_G_Exception' => 'Una excepción: un cambio de stock hecho por una tarea en segundo plano no tiene ninguna respuesta tras la cual ejecutarse, así que se pone en la cola {queue}.',
'Shp_G_Queue_Managed' => 'Su plataforma ya ejecuta un worker en esa cola, así que esos cambios también se envían por sí solos.',
'Shp_G_Queue_Cron' => 'Si quiere que esos cambios también se envíen sin demora, procese esa cola:',
'Shp_G_On_Schedule' => 'Según una programación',
'Shp_G_On_Lc' => 'activado',
'Shp_G_Off_Lc' => 'desactivado',
'Shp_G_Scheduled_Lead' => 'Todo se vuelve a comprobar cada cierto tiempo, en ambas direcciones. Es más lento que el tiempo real, pero es lo que envía el stock en las tiendas que no usan el envío instantáneo, lo que recupera un webhook perdido y la única forma de mover un catálogo completo.',
'Shp_G_Nothing_To_Install' => 'Nada que instalar',
'Shp_G_Managed_Body' => 'El programador se ejecuta por usted: cada cinco minutos su plataforma pregunta a cada tienda si le toca algún paso de su plan y ejecuta los que correspondan. No hay que añadir ninguna entrada de cron ni mantener ningún servidor.',
'Shp_G_Managed_Note' => 'Cinco minutos es también la resolución más fina que puede usar un plan, porque es el intervalo de paso más corto. Los intervalos más largos se respetan con exactitud: un paso configurado a 30 minutos se comprueba seis veces y se ejecuta una.',
'Shp_G_Cron_Entry' => 'La entrada de cron',
'Shp_G_Cron_Body' => 'Sin ella no se ejecuta nada programado. Una sola línea, solo para este módulo; añádala junto a lo que ya haya decidido programar:',
'Shp_G_Cron_Note' => 'Cada cinco minutos es la resolución más fina que puede usar un plan, porque cinco minutos es el intervalo de paso más corto. Una entrada menos frecuente simplemente se convierte en el mínimo: con {every15}, un paso configurado a 5 minutos se ejecuta cada 15. En Windows, use el Programador de tareas: programa {php}, argumentos {args}, iniciar en {path}.',
'Shp_G_Switch_On' => 'Actívelo y elija el plan',
'Shp_G_Plan_Body' => '{path} El interruptor decide si el programador puede actuar; el plan decide qué hace. Un {step} es una entidad en una dirección con su propio intervalo: {ex1}, {ex2}. El intervalo predeterminado lo usa cualquier paso que deje su campo vacío.',
'Shp_G_Step_Lc' => 'paso',
'Shp_G_Ex1' => 'Pedidos · Shopify → ERP cada 15 min',
'Shp_G_Ex2' => 'Inventario · ERP → Shopify cada 30 min',
'Shp_G_Plan_Note' => 'Si deja el plan vacío, la tienda obtiene los pedidos y envía el stock con el intervalo predeterminado, que es lo que quieren la mayoría de las tiendas. Los pedidos solo se obtienen: Shopify es donde el cliente los realiza.',
'Shp_G_Schedule_On' => 'programación activada',
'Shp_G_Schedule_Off' => 'programación desactivada — solo manual',
'Shp_G_When_Runs' => 'Cuándo se ejecuta realmente un paso',
'Shp_G_When_Body' => 'Un paso vence cuando ese mismo paso se {started} por última vez hace más tiempo que su intervalo, según el historial de ejecuciones. Así, una sincronización que inicia manualmente aplaza la siguiente automática, y un paso que falla repetidamente se reintenta según su intervalo, no en cada ciclo. El Resumen de la tienda muestra la última ejecución de cada paso, la próxima ejecución prevista y, si está bloqueado, el motivo. Ejecute el primer envío del catálogo manualmente desde el Centro de sincronización (primero como simulación) antes de programarlo.',
'Shp_G_Started_Lc' => 'inició',
'Shp_G_Where_Setting' => 'Dónde está cada ajuste',
'Shp_G_Where_Note' => 'Todos están en una tienda existente: {path}, luego el lápiz (o {edit} en la propia página de la tienda).',
'Shp_G_Product_Images' => 'Imágenes de productos',
'Shp_G_Img1' => 'Las imágenes se envían con el producto en un {push}: primero la imagen principal, luego la galería y después una por cada variante que tenga la suya propia, hasta cincuenta.',
'Shp_G_Products_Push' => 'envío de productos',
'Shp_G_Img2' => 'La imagen de una variante se sube con el producto y luego se {assigned}, que es como lo modela Shopify: una variante apunta a una de las imágenes del producto. Una variante que reutiliza la imagen principal no la sube dos veces.',
'Shp_G_Assigned' => 'asigna a esa variante',
'Shp_G_Img3' => 'Una imagen guardada como archivo se {uploaded} a Shopify, no se enlaza, así que funciona incluso cuando esta instalación no es accesible desde internet. Una imagen añadida como enlace pegado se entrega a Shopify como esa URL, que debe ser accesible públicamente.',
'Shp_G_Uploaded' => 'sube',
'Shp_G_Img4' => 'Solo se vuelven a enviar cuando realmente cambian: un envío que solo modifica un precio no toca las imágenes de la tienda, porque enviarlas reemplaza el conjunto completo.',
'Shp_G_Img5' => 'Eliminar una imagen en el ERP {not} la elimina en Shopify. Elimínela allí también, o la tienda seguirá mostrándola.',
'Shp_G_Commands' => 'Comandos útiles',
'Shp_G_Command_Copied' => 'Comando copiado',
'Shp_G_Foot' => 'Cada sincronización escribe en {logs}, y el Resumen de cada tienda muestra cuándo se ejecutó cada paso por última vez, cuándo le toca de nuevo y qué lo bloquea, si algo lo hace. Ahí es donde debe mirar primero cuando una sincronización no hizo lo que esperaba.',
'Shp_G_Covers' => 'Cubre',
'Shp_G_Speed' => 'Velocidad',
'Shp_G_Needs' => 'Requiere',
'Shp_G_Switched_On_At' => 'Se activa en',
'Shp_G_Way_Covers_Rt' => 'Pedidos y ediciones hechos en Shopify; stock que sale del ERP (una venta POS, una devolución, un ajuste)',
'Shp_G_Way_Covers_Sc' => 'Todo, en ambas direcciones, incluidos los envíos del catálogo y cualquier cosa que la vía rápida haya pasado por alto',
'Shp_G_Seconds' => 'Segundos',
'Shp_G_Way_Speed_Sc' => 'El intervalo del paso (de 5 minutos a 7 días)',
'Shp_G_Way_Needs_Rt' => 'Una dirección HTTPS pública y el secreto de firma para los webhooks entrantes. El stock saliente no necesita nada',
'Shp_G_Way_Needs_Sc' => 'El programador, cada cinco minutos',
'Shp_G_Way_Switch_Sc' => '{path}, más el plan',
'Shp_G_Scope_Orders' => '{a} ({b} para pedidos de más de 60 días)',
'Shp_G_Admin_Scopes' => 'Permisos (scopes) de Admin API',
'Shp_G_Setting' => 'Ajuste',
'Shp_G_Tab_In_Edit' => 'Pestaña en Editar tienda',
'Shp_G_Set1' => 'Client ID + secret o token de acceso, secreto de firma, versión de la API',
'Shp_G_What1' => 'Las credenciales de la app de Shopify (Dev Dashboard o app personalizada heredada).',
'Shp_G_Set2' => 'Almacén del ERP, ubicación de Shopify',
'Shp_G_What2' => 'Qué stock vende esta tienda y dónde se registran los pedidos.',
'Shp_G_What3' => 'Precio de venta al público, mayorista o mínimo.',
'Shp_G_Set4' => 'Crear productos / clientes que falten',
'Shp_G_What4' => 'Si una importación puede crear registros del ERP que no logra emparejar.',
'Shp_G_Set5' => 'Qué entidades se sincronizan',
'Shp_G_What5' => 'Desactivado aquí significa desactivado en todas partes: manual, programado y por webhook.',
'Shp_G_What6' => 'El interruptor del programador.',
'Shp_G_What7' => 'Envío instantáneo de stock, encolado al hacer una venta o un ajuste.',
'Shp_G_Set8' => 'Intervalo predeterminado y plan de pasos',
'Shp_G_What8' => 'Qué se ejecuta por sí solo, en qué dirección y con qué frecuencia.',
'Shp_G_Cmd1' => 'Todas las tiendas: qué se ejecutaría y cuándo. No cambia nada.',
'Shp_G_Cmd2' => 'Todo el plan de una tienda ahora mismo, ignorando el reloj.',
'Shp_G_Cmd3' => 'Primer envío del catálogo: solo los productos aún no vinculados.',
'Shp_G_Cmd4' => 'Recuperar pedidos desde una fecha.',
'Shp_G_Cmd5' => 'Recorrerlo e informar, sin escribir nada en ningún sitio.',
'Shp_Guide_Subtitle' => 'Conectar una tienda, qué se ejecuta por sí solo y dónde está cada ajuste',
'Shp_Show_Store_State' => 'Mostrar el estado de una tienda',
'Shp_Open_Store' => 'Abrir tienda',
'Shp_No_Shop_Connected_Yet' => 'Todavía no hay ninguna tienda conectada',
'Shp_Guide_No_Shop_Desc' => 'Todo lo que se explica a continuación sigue siendo válido: conecte una desde Shopify → Tiendas y luego vuelva aquí y elíjala arriba para ver su propio estado junto a cada paso.',

