'Agt_Series' => 'Series',
'Agt_Series_Hint' => 'La AGT autoriza una serie de numeración por tipo de documento, año y establecimiento. No se pueden emitir facturas sin una serie activa para su tipo y año.',
'Agt_Request_Series' => 'Solicitar serie a la AGT',
'Agt_Add_Series' => 'Añadir serie existente',
