'Normal' => 'Normal',
'Agt_Corrects' => 'Corrige',
'Agt_Late' => '> 24h',
'Agt_Check' => 'Consultar',
'Agt_Correct_Confirm' => '¿Emitir una corrección con un número nuevo para este documento rechazado?',
'Agt_Correct' => 'Corregir',
'Agt_Guide_What_Title' => 'Qué hace',
'Agt_Guide_What_Body' => 'Cada venta completada se emite como factura electrónica AGT (FR si se paga al crearse, de lo contrario FT) y cada devolución recibida como nota de crédito (NC). Cada documento recibe el siguiente número de su serie AGT, se firma con su clave AGT y se envía a la AGT, que lo valida unos minutos después. El recibo y la factura en PDF imprimen el número AGT, el extracto de seguridad y un código QR.',
'Agt_Guide_Steps_Title' => 'Configuración',
'Agt_Guide_Step_1' => 'Adhiérase a la facturación electrónica (adesão) en el Portal do Contribuinte y descargue su clave privada AGT.',
'Agt_Guide_Step_2' => 'Introduzca su NIF, el establecimiento y la clave en la pestaña Configuración, elija Homologação, guarde y use Probar conexión.',
'Agt_Guide_Step_3' => 'En la pestaña Series, solicite una serie por cada tipo de documento que utilice (FR, FT, NC) para el año en curso.',
'Agt_Guide_Step_4' => 'Asigne sus tasas de IVA a los códigos AGT y defina el código de exención para las líneas al 0%.',
'Agt_Guide_Step_5' => 'Active el módulo en Ajustes del sistema > Características, haga una venta de prueba y compruebe que pasa a válida en la pestaña Documentos.',
'Agt_Guide_Step_6' => 'Cuando la AGT le apruebe para producción, cambie a Produção y solicite series de producción.',
'Agt_Guide_Note_1' => 'Una venta o devolución comunicada ya no se puede editar ni eliminar. Corríjala con una devolución de venta (nota de crédito).',
'Agt_Guide_Note_2' => 'Los documentos rechazados por la AGT se corrigen con un número nuevo que hace referencia al rechazado; el número anterior nunca se reutiliza.',
'Agt_Guide_Note_3' => 'Las ventas del POS sin conexión se comunican cuando se sincronizan. La AGT sanciona los documentos enviados con más de 24 horas de retraso.',
'Agt_Guide_Note_4' => 'Una línea no puede llevar a la vez un impuesto de producto y el impuesto del pedido; la AGT necesita una tasa de IVA por línea. El envío se envía como línea exenta.',
'Agt_Guide_Note_5' => 'Los totales de la AGT se calculan por línea y pueden diferir del total de Stocky en unos céntimos por redondeo.',
