'Dgi_Api_Pending_Body' => 'La DGI publica la API para desarrolladores del e-MCF solo a desarrolladores registrados (developper.dgirdc.cd). Hasta que se conecte, las facturas llevan sus menciones NIF / RCCM / Id. Nat., pero no el número DEF, el código de autenticación ni el QR.',
