'Dgi_No_Documents' => 'Aún no hay facturas certificadas — la certificación comienza cuando la conexión e-MCF esté activa.',
'Dgi_Guide_What_Title' => 'Qué hace actualmente',
'Dgi_Guide_What_Body' => 'Con el módulo activado, los recibos y las facturas en PDF imprimen el NIF, el RCCM y el Id. Nat. del vendedor exigidos en la facture normalisée. La certificación completa (número DEF, contadores, código de autenticación y QR devueltos por la DGI) se añadirá cuando la API para desarrolladores del e-MCF esté conectada.',
'Dgi_Guide_Steps_Title' => 'Obtener acceso al e-MCF',
'Dgi_Guide_Step_1' => 'Cree una cuenta con su NIF en developper.dgirdc.cd y solicite acceso al entorno de pruebas del e-MCF.',
'Dgi_Guide_Step_2' => 'Descargue la documentación de la API (rutas, DTO, grupos de tributación) y las credenciales de prueba.',
'Dgi_Guide_Step_3' => 'Envíelas al administrador de su plataforma para que pueda completar y probar la conexión.',
'Dgi_Guide_Step_4' => 'Después de las pruebas, presente el expediente de homologación a la DGI.',
