'Variant_Missing_Option_Values' => 'Cada variante necesita un valor para cada opción.',
'Fashion_Theme' => 'Tema de moda y ropa',
'Fashion_Theme_Hint' => 'Tienda de ropa de estilo editorial: títulos con serifa, fotos grandes, mosaicos de categorías, novedades con pestañas por categoría, un banner de lookbook y una fila de rebajas. Las tarjetas de producto muestran las tallas (las agotadas, tachadas) y cambian a la segunda foto de la galería al pasar el cursor. Su color principal se usa en los precios rebajados y las insignias. El carrusel principal y los banners de lookbook aparecen cuando los añade abajo.',
