'Commission_Guide' => 'Guía de comisiones',
'Comm_G_Intro_Title' => 'Cómo funcionan las comisiones, en una frase',
'Comm_G_Intro' => 'Cuando se guarda una venta completada, las reglas que coinciden con el agente de ventas de la venta crean comisiones Pendientes. Usted las aprueba en el Informe de comisiones y las paga con un Recibo de comisión. Si la venta cambia después (pagos, devoluciones, ediciones, eliminación), sus comisiones se recalculan automáticamente.',
'Comm_G_Your_Setup' => 'Su configuración',
'Comm_G_Your_Setup_Help' => 'Estado en tiempo real de este espacio de trabajo. Cada paso se vuelve verde cuando está hecho.',
'Comm_G_Optional' => 'Recomendado',
'Comm_G_Step_Program' => 'Crear un programa de comisiones',
'Comm_G_Step_Program_Help' => 'Un programa agrupa sus reglas, por ejemplo "Equipo de ventas 2026" o "Campaña de verano". Debe estar Activo y la fecha de hoy debe estar entre sus fechas Válido desde y Válido hasta.',
'Comm_G_Step_Program_Warn' => 'Tiene programas, pero ninguno está activo hoy. Revise la casilla Activo y las fechas Válido desde / Válido hasta.',
'Comm_G_Step_Agent' => 'Añadir sus agentes de ventas',
'Comm_G_Step_Agent_Help' => 'Un agente de ventas es la persona que gana la comisión. Los agentes pueden ser miembros del personal o personas externas, como referidores o revendedores.',
'Comm_G_Step_Link' => 'Vincular agentes a cuentas de usuario',
'Comm_G_Step_Link_Help' => 'Vincular un agente a un usuario permite que las ventas realizadas por ese usuario se acrediten al agente automáticamente, sin tener que elegir el agente en cada venta.',
'Comm_G_Step_Link_Warn' => '{n} agente(s) activo(s) no están vinculados a un usuario. Solo ganan cuando alguien los elige en la venta.',
'Comm_G_Step_Rule' => 'Añadir al menos una regla',
'Comm_G_Step_Rule_Help' => 'Una regla indica cuánto pagar, por ejemplo el 5% del total de la venta. Debe estar Activa y pertenecer a un programa que esté activo hoy.',
'Comm_G_Step_Rule_Warn' => 'Tiene reglas, pero ninguna está activa dentro de un programa que esté activo hoy.',
'Comm_G_Step_Sale' => 'Realizar una venta completada',
'Comm_G_Step_Sale_Help' => 'Las comisiones se crean cuando se guarda una venta completada (Crear venta, Editar venta o POS). Las ventas realizadas antes de que existieran sus reglas no se calculan.',
'Comm_G_Step_Sale_Done' => '{n} comisión(es) calculada(s) hasta ahora.',
'Comm_G_Step_Approve' => 'Aprobar comisiones',
'Comm_G_Step_Approve_Help' => 'En el Informe de comisiones, marque las filas Pendientes con las que esté de acuerdo y haga clic en Aprobado. Ahora mismo no hay nada en espera.',
'Comm_G_Step_Approve_Warn' => '{n} comisión(es) en espera de aprobación.',
'Comm_G_Step_Pay' => 'Pagar a sus agentes',
'Comm_G_Step_Pay_Help' => 'En Recibos de comisión, elija un agente, marque sus comisiones Aprobadas y guarde el recibo. Pasan a Pagadas. Ahora mismo no hay nada pendiente de pago.',
'Comm_G_Step_Pay_Warn' => '{n} comisión(es) aprobada(s) en espera de pago.',
'Comm_G_Try_Rule' => 'Probar una regla',
'Comm_G_Try_Rule_Help' => 'Introduzca una venta y una regla para ver exactamente lo que pagaría la regla. El cálculo es el mismo que usa el sistema.',
