'Comm_G_Flow_Rule_Help' => 'Dentro del programa, añada reglas: porcentaje o fijo, para todos los agentes o para un agente.',
'Comm_G_Flow_Sale' => 'Venta',
'Comm_G_Flow_Sale_Help' => 'Se guarda una venta completada. Cada regla que coincide crea una comisión Pendiente.',
