'Comm_G_Flow_Pay_Help' => 'Registre un Recibo de comisión para el agente. Las comisiones que cubre pasan a Pagadas.',
'Comm_G_How_It_Works' => 'Cómo funciona',
'Comm_G_T_Credit' => '¿Qué agente recibe la comisión?',
'Comm_G_Credit_Intro' => 'Cada venta se acredita como máximo a un agente. El sistema comprueba, en este orden:',
'Comm_G_Credit_Picked' => 'El agente de ventas elegido en la venta: el campo Agente de ventas en Crear venta y Editar venta, o el botón "Vendido por" en el POS. Si ese agente se ha desactivado desde entonces, la venta no genera nada; no pasa a las opciones siguientes.',
'Comm_G_Credit_Seller' => 'Si no, el agente vinculado al vendedor elegido en el POS (cuando el interruptor de vendedor del POS está activado).',
'Comm_G_Credit_Cashier' => 'Si no, el agente vinculado al usuario que guardó la venta.',
'Comm_G_Credit_Nobody' => 'Si ninguna de estas opciones encuentra un agente activo, la venta no genera comisión.',
'Comm_G_Credit_Note' => 'En el POS, dejar el agente en "Automático" utiliza las opciones 2 y 3. El nombre que aparece junto a "Automático" es el agente al que se acreditará.',
'Comm_G_T_When' => '¿Cuándo se calculan y actualizan las comisiones?',
'Comm_G_When_Intro' => 'Las comisiones se crean por primera vez cuando se guarda una venta con estado Completada, en cualquiera de estos lugares:',
'Comm_G_When_Create' => 'Crear venta: cuando la venta se guarda como Completada.',
'Comm_G_When_Edit' => 'Editar venta: al guardar una venta Completada se recalcula desde cero con su total, pagos y agente actuales, incluidas las comisiones que se habían cancelado.',
'Comm_G_When_Pos' => 'POS: cuando se completa una venta, incluido un borrador que se completa más tarde.',
'Comm_G_When_Payment' => 'Al añadir un pago a una venta Completada, que es lo que permite que las reglas de Cantidad pagada recojan los pagos recibidos después de la venta.',
'Comm_G_When_Cod' => 'Contra entrega del mensajero: cuando el efectivo cobrado por el mensajero se registra como pago de la venta.',
'Comm_G_When_Not_Intro' => 'Estos NO crean comisiones:',
'Comm_G_When_Not_Status' => 'Ventas guardadas como Pendiente u Ordenado. Empiezan a generar comisiones cuando se editan y se guardan como Completada.',
'Comm_G_When_Not_Before' => 'Ventas guardadas antes de que existiera el programa o la regla. No se calculan en segundo plano. Abrir una de esas ventas en Editar venta y guardarla la calcula con las reglas activas en la fecha de la venta.',
'Comm_G_When_Not_Import' => 'Ventas importadas desde un archivo.',
'Comm_G_When_Not_Online' => 'Pedidos realizados en la tienda en línea.',
'Comm_G_T_Statuses' => 'Estados de las comisiones',
'Comm_G_Meaning' => 'Qué significa',
'Comm_G_S_Pending' => 'Recién calculada a partir de una venta. Nadie la ha revisado todavía. Apruébela o cancélela en el Informe de comisiones.',
'Comm_G_S_Approved' => 'Revisada y aceptada. Se le debe al agente y puede incluirse en un Recibo de comisión. Si la venta cambia y el importe cambia, vuelve a Pendiente para otra revisión.',
'Comm_G_S_Paid' => 'Incluida en un Recibo de comisión. Definitiva: las comisiones pagadas nunca se modifican. Si la venta cambia después, la diferencia se añade como un Ajuste aparte.',
'Comm_G_S_Cancelled' => 'No se pagará. Sigue cancelada aunque lleguen pagos o devoluciones más tarde. Guardar la venta en Editar venta, o marcarla en el informe y hacer clic en Recalcular, la vuelve a calcular.',
'Comm_G_Field' => 'Campo',
'Comm_G_T_Programs' => 'Programas de comisión',
'Comm_G_Programs_Body' => 'Un programa es un contenedor de reglas, normalmente uno por período o campaña. Una regla solo funciona mientras su programa está Activo y la fecha de la venta está dentro de las fechas del programa. Puede haber varios programas activos al mismo tiempo, y todos se aplican.',
'Comm_G_F_Program_Name' => 'Cualquier nombre que le ayude a reconocer el programa, por ejemplo "T4 2026" o "Black Friday".',
'Comm_G_F_Program_Active' => 'Desmárquelo para pausar todas las reglas del programa a la vez. Las comisiones ya creadas no se ven afectadas.',
'Comm_G_F_Program_From' => 'El programa ignora las ventas con fecha anterior a este día. Déjelo vacío para no tener fecha de inicio.',
'Comm_G_F_Program_To' => 'El programa ignora las ventas con fecha posterior a este día. Déjelo vacío para un programa que no termina nunca.',
'Comm_G_T_Agents' => 'Agentes de ventas',
'Comm_G_Agents_Body' => 'Un agente de ventas es la persona que gana la comisión. Un agente no necesita ser usuario del sistema: los referidores o revendedores externos también pueden ser agentes, y ganan cada vez que se les elige en una venta.',
'Comm_G_F_Agent_Name' => 'El nombre que aparece en las ventas, el informe y los recibos.',
'Comm_G_F_Agent_Code' => 'Referencia opcional, como un número de empleado. Se puede buscar en la lista de agentes.',
'Comm_G_F_Agent_User' => 'Vincula el agente a un usuario del personal. Las ventas que realiza ese usuario (o en las que se le elige como vendedor en el POS) se acreditan entonces automáticamente a este agente.',
'Comm_G_F_Agent_Active' => 'Los agentes inactivos no ganan nada en las ventas nuevas y desaparecen de los selectores de agentes. Sus comisiones anteriores se conservan.',
'Comm_G_T_Rules' => 'Reglas de comisión: cada campo explicado',
'Comm_G_Rules_Body' => 'Una regla decide cuánto se paga en una venta. Use el cuadro "Probar una regla" de arriba para comprobar una regla antes de guardarla.',
'Comm_G_F_Rule_Program' => 'El programa al que pertenece la regla. La regla solo funciona mientras ese programa está activo y dentro de sus fechas.',
'Comm_G_F_Rule_Type' => 'Porcentaje paga una parte del importe base. Fijo paga el mismo importe en cada venta que califique, sea cual sea su tamaño.',
'Comm_G_F_Rule_Source' => 'Sobre qué se calcula el porcentaje. Total de venta es el total general de la venta. Cantidad pagada es lo que el cliente había pagado cuando se calculó la comisión.',
'Comm_G_F_Rule_Value' => 'El porcentaje (5 significa 5%) o el importe fijo, según el Tipo.',
'Comm_G_F_Rule_Min' => 'Opcional. Las ventas cuyo importe base esté por debajo de este valor no generan nada con esta regla. Una venta exactamente igual al umbral sí genera comisión.',
'Comm_G_F_Rule_Cap' => 'Opcional. Lo máximo que esta regla puede pagar en una venta. Funciona tanto para reglas de porcentaje como fijas.',
'Comm_G_F_Rule_Applies' => 'Todos los agentes: todos los agentes ganan con esta regla. Agente específico: solo el agente que seleccione. Una regla de Agente específico sin agente seleccionado nunca paga a nadie.',
'Comm_G_F_Rule_Priority' => 'En un programa configurado como "Solo paga la regla de mayor prioridad", gana la regla que califica con el número más alto y las demás se omiten. En caso de empate, una regla de Agente específico gana a una de Todos los agentes. En un programa configurado como "Pagan todas las reglas que coinciden", la Prioridad solo define el orden.',
'Comm_G_F_Rule_Active' => 'Desmárquelo para pausar solo esta regla. Las comisiones que ya creó no se ven afectadas.',
'Comm_G_T_Stacking' => 'Varias reglas en una venta',
'Comm_G_Stacking_Body' => 'Cada programa decide cómo se combinan sus reglas (el ajuste "Cuando coinciden varias reglas" del programa).

Solo paga la regla de mayor prioridad (el valor predeterminado para programas nuevos): las reglas se prueban de la Prioridad más alta a la más baja, y paga la primera que califica para la venta. Una regla califica cuando la venta alcanza su umbral mínimo y el resultado es mayor que 0. Así es fácil crear escalones: "7% en ventas de 10,000 o más" con prioridad 10 y "5%" con prioridad 0. Para dar a Sara una tasa especial, añada una regla de Agente específico para ella con una prioridad más alta que la regla de Todos los agentes.

Pagan todas las reglas que coinciden: todas las reglas que coinciden pagan y los importes se suman. Una regla de Todos los agentes del 3% más una regla de Agente específico del 2% para Sara le dan a Sara un 5%.

Los programas son independientes entre sí: cada programa activo paga por su cuenta, de modo que una venta puede generar comisión de un programa base y de un programa de campaña al mismo tiempo.',
'Comm_G_T_Paying' => 'Pagar a los agentes con Recibos de comisión',
'Comm_G_Paying_Body' => 'Abra Recibos de comisión y haga clic en Añadir. Elija el agente: se listan sus comisiones Aprobadas. Marque las que va a pagar; el Importe se completa con su total y puede ajustarlo. La Ref. se completa automáticamente (CR-000001, CR-000002...) y puede añadir el método de pago, la fecha y una nota.

Al guardar el recibo, las comisiones marcadas pasan a Pagadas y quedan vinculadas al recibo. Solo se pueden pagar las comisiones Aprobadas, así que apruébelas primero en el Informe de comisiones.

Los Ajustes negativos (dinero pagado de más al agente) también aparecen en la lista. Márquelos junto con las siguientes comisiones del agente para que se descuenten de ese pago.

Un recibo es solo un registro del pago: no crea un gasto ni mueve dinero en sus cuentas. Si registra los pagos en Gastos o Contabilidad, regístrelos también allí.',
'Comm_G_T_Snapshot' => 'Cuando cambia una venta',
'Comm_G_Snapshot_Body' => 'Las comisiones siguen a la venta. Siempre que cambia una venta que tiene comisiones, estas se recalculan a partir de sus cifras actuales: el total de la venta menos las devoluciones recibidas, y el importe pagado menos los reembolsos.

Las comisiones no pagadas (Pendientes o Aprobadas) simplemente se actualizan. Una comisión Aprobada cuyo importe cambia vuelve a Pendiente para que alguien la revise de nuevo. La que ya no se debe (venta eliminada, devuelta por completo, agente cambiado) se elimina.

Las comisiones pagadas nunca se modifican. La diferencia se convierte en una nueva fila Pendiente marcada como Ajuste: positiva cuando se debe más (por ejemplo, se pagó el resto de una venta con regla de Cantidad pagada) y negativa cuando se pagó de más al agente (por ejemplo, tras una devolución). Apruébela e inclúyala en el siguiente recibo del agente.

Cada comisión conserva las condiciones de la regla (tipo, tasa, umbral, límite) del momento en que se generó por primera vez. Cambiar o desactivar una regla más tarde no recalcula el precio de las ventas anteriores cuando se recalculan.',
'Comm_G_T_Permissions' => 'Quién puede hacer qué',
'Comm_G_Permission' => 'Permiso',
'Comm_G_Lets_You' => 'Qué permite',
'Comm_G_P_View' => 'Ver todas las páginas de Comisiones: programas, agentes, reglas, recibos, el informe y esta guía.',
'Comm_G_P_Add' => 'Crear programas, agentes y reglas, y registrar Recibos de comisión (pagar a los agentes).',
'Comm_G_P_Edit' => 'Editar programas, agentes y reglas, y aprobar o cancelar comisiones en el Informe de comisiones.',
'Comm_G_P_Delete' => 'Eliminar programas, agentes y reglas.',
'Comm_G_T_Faq' => 'Preguntas y respuestas',
'Comm_G_Q_Empty' => 'Lo configuré todo, pero el Informe de comisiones está vacío.',
'Comm_G_A_Empty' => 'Compruebe que: la venta se guardó después de crear la regla; la venta está Completada; la venta tiene un agente (elegido en la venta, o el usuario que la hizo está vinculado a un agente); el programa está activo y la fecha de la venta está dentro de sus fechas; la regla está activa y se aplica a ese agente; y la venta alcanza o supera el umbral mínimo de la regla. Revise también el filtro de fechas del informe: filtra por la fecha en que se calculó la comisión.',
'Comm_G_Q_Twice' => 'Un agente recibió dos comisiones por una misma venta.',
'Comm_G_A_Twice' => 'Pagaron dos reglas: o bien el programa está configurado como "Pagan todas las reglas que coinciden", o bien las reglas están en dos programas activos distintos (cada programa paga por su cuenta). Configure el programa como "Solo paga la regla de mayor prioridad" si solo debe pagar una. Volver a guardar una venta nunca duplica una comisión.',
'Comm_G_Q_Rate' => 'Si cambio la tasa de una regla, ¿cambian las comisiones anteriores?',
'Comm_G_A_Rate' => 'No. Cada comisión conserva las condiciones de la regla con la que se generó, aunque su venta se recalcule más tarde. La nueva tasa se usa para las comisiones generadas a partir de ahora.',
'Comm_G_Q_Return' => 'El cliente devolvió la mercancía. ¿Qué pasa con la comisión?',
'Comm_G_A_Return' => 'Se reduce automáticamente. Una devolución recibida reduce el total de la venta y un reembolso reduce el importe pagado. Si la comisión aún no se había pagado, se actualiza (o se elimina en una devolución completa). Si ya se había pagado, se añade un Ajuste negativo que se descuenta del siguiente recibo del agente.',
'Comm_G_Q_Wrong_Agent' => 'Acredité al agente equivocado. ¿Cómo lo corrijo?',
'Comm_G_A_Wrong_Agent' => 'Edite la venta, elija el Agente de ventas correcto y guarde. Las comisiones pasan al agente correcto. Si al primer agente ya se le había pagado, se añade un Ajuste negativo para él.',
'Comm_G_Q_Inactive' => '¿Qué ocurre cuando desactivo a un agente?',
'Comm_G_A_Inactive' => 'Deja de ganar en las ventas nuevas y se oculta de los selectores de agentes. Sus comisiones existentes se conservan, todavía se pueden aprobar y pagar, y siguen reflejando los cambios en sus ventas. Una venta guardada con ese agente elegido no pasará a otro agente.',
'Comm_G_Q_Partial' => '¿Cómo gestionan los pagos parciales las reglas de Cantidad pagada?',
'Comm_G_A_Partial' => 'Una venta no pagada no genera nada. La comisión se crea cuando se recibe dinero por primera vez (al cobrar o cuando se añade un pago) y aumenta a medida que llegan más pagos. Si ya se había pagado una parte, el resto llega como un Ajuste positivo.',
'Comm_G_Q_Undo' => '¿Puedo deshacer un pago o una cancelación?',
'Comm_G_A_Undo' => 'Un pago, no: Pagada es definitivo y los recibos no se pueden editar ni eliminar, así que revise las comisiones marcadas y el importe antes de guardar. Una cancelación, sí: marque la fila en el Informe de comisiones y haga clic en Recalcular, o vuelva a guardar la venta en Editar venta.',
'Comm_G_Q_Dates' => '¿Qué fecha usan las fechas del programa?',
'Comm_G_A_Dates' => 'La fecha propia de la venta, no el día en que se guardó. Una venta con fecha del mes pasado solo usa programas que eran válidos el mes pasado.',
'Comm_G_When_Changes' => 'Después, cualquier cambio en una venta que ya tiene comisiones las actualiza automáticamente: pagos editados o eliminados, devoluciones y reembolsos, que el estado deje de ser Completada, o la eliminación de la venta.',
'Comm_G_F_Program_Mode' => 'Qué ocurre cuando varias reglas de este programa coinciden con la misma venta. "Solo paga la regla de mayor prioridad": las reglas se prueban de la Prioridad más alta a la más baja y paga la primera que califica. "Pagan todas las reglas que coinciden": todas pagan y los importes se suman.',
'Comm_G_Q_Mode_Old' => 'Definí prioridades, pero las reglas siguen sumándose.',
'Comm_G_A_Mode_Old' => 'Ese programa está configurado como "Pagan todas las reglas que coinciden". Los programas creados antes de que existiera este ajuste mantienen ese comportamiento para que sus pagos no cambien. Edite el programa y elija "Solo paga la regla de mayor prioridad".',
'Comm_G_Q_Negative' => '¿Por qué hay una comisión negativa?',
'Comm_G_A_Negative' => 'Es un Ajuste: al agente se le pagó más de lo que la venta genera ahora, debido a una devolución, un reembolso, un total menor, un cambio de agente o una venta eliminada. Apruébelo y márquelo en el siguiente recibo del agente para que se descuente.',
'Comm_Rule_Mode' => 'Cuando coinciden varias reglas',
'Comm_Mode_Highest' => 'Solo paga la regla de mayor prioridad',
'Comm_Mode_All' => 'Pagan todas las reglas que coinciden (se suman)',
'Comm_Mode_Highest_Short' => 'Gana la mayor prioridad',
'Comm_Mode_All_Short' => 'Las reglas se suman',
'Comm_Mode_Highest_Help' => 'Las reglas se prueban de la Prioridad más alta a la más baja; paga la primera que califica para la venta y las demás se omiten. Ideal para escalones, por ejemplo 7% por encima de 10,000 con prioridad 10 y 5% para todo lo demás con prioridad 0.',
'Comm_Mode_All_Help' => 'Cada regla que coincide con el agente paga en la venta, por lo que los importes se suman. La Prioridad solo define el orden.',
'Comm_Priority_Help_Highest' => 'Este programa solo paga la regla de mayor prioridad que califica. Asigne a esta regla una Prioridad más alta que las reglas a las que deba ganar. En caso de empate, una regla de Agente específico gana a una de Todos los agentes.',
'Comm_Priority_Help_All' => 'Este programa paga todas las reglas que coinciden, por lo que esta regla se suma a las demás. La Prioridad solo define el orden.',
'Comm_Recalculate' => 'Recalcular',
'Comm_Recalculate_Help' => 'Vuelve a calcular las ventas de las filas marcadas a partir de sus cifras actuales, incluidas las comisiones que se cancelaron.',
'Comm_Adjustment' => 'Ajuste',
'Comm_Adjustment_Help' => 'Una corrección de una comisión que ya se pagó, porque la venta cambió después. Un importe negativo se descuenta del siguiente recibo del agente.',
'Comm_Cancel_Confirm' => '¿Cancelar las comisiones seleccionadas?',
'Comm_Cancel_Confirm_Help' => 'No se pagarán y seguirán canceladas aunque lleguen pagos o devoluciones más tarde. Guardar la venta en Editar venta o hacer clic en Recalcular las vuelve a calcular.',
'Fashion_Tiles_Hint' => 'Añada sus propios mosaicos (imagen, título y enlace) para reemplazar los mosaicos de categorías automáticos.',

// Online Store: Car Dealership theme
'Car_Dealership_Theme' => 'Tema de concesionario de vehículos',
'Cars_Theme_Hint' => 'Los vehículos son productos normales: añada el precio, las fotos y la descripción como siempre y luego complete la tarjeta Detalles del vehículo en el formulario del producto (marca, modelo, año, kilometraje …). Los compradores envían consultas, solicitudes de prueba de conducción y tasaciones de vehículos en parte de pago, que llegan a Tienda › Prospectos de vehículos.',
