'Cars_Reserve_Product' => 'Producto de depósito',
'Cars_Reserve_Product_Hint' => 'Cree un producto de servicio llamado, por ejemplo, "Depósito de reserva" con el importe del depósito como precio y luego elíjalo aquí. Reservar un vehículo registra un prospecto y pone este producto en el carrito. Nunca aparece en el inventario.',
