// Restaurant Management — guide page
'Rst_Guide' => 'Guía',
'Rst_Guide_Subtitle' => 'Configure el restaurante y aprenda paso a paso cómo funciona un servicio',
'Rst_Guide_Module_Off' => 'El módulo Restaurante no está activo para esta cuenta',
'Rst_Guide_Module_Off_Help' => 'Necesita la función Restaurante en su plan y el módulo activado en Configuración › Módulos. Los pedidos online, los menús QR y la reserva online permanecen ocultos hasta entonces.',
'Rst_Guide_Your_Setup' => 'Su configuración',
'Rst_Guide_Your_Setup_Help' => 'Se comprueba con sus propios datos cada vez que abre esta página. Avance de arriba abajo; los pasos opcionales pueden esperar.',
'Rst_Guide_Done_N' => '{done} de {total} completados',
'Rst_Guide_Optional' => 'Opcional',
