'Rst_Guide_State_Warn' => 'Requiere atención',
'Rst_Guide_State_Todo' => 'Pendiente',
'Rst_Guide_Step_Db' => 'Actualización de la base de datos',
'Rst_Guide_Step_Db_Ok' => 'Todas las tablas del restaurante están creadas.',
'Rst_Guide_Step_Db_Help' => 'Faltan algunas tablas del restaurante. Ejecute la última actualización de la base de datos (migraciones del inquilino) y vuelva a cargar esta página.',
'Rst_Guide_Step_Settings' => 'Configuración del restaurante',
'Rst_Guide_Step_Settings_Ok' => 'Tipos de pedido: {types}. Hay una sucursal predeterminada.',
'Rst_Guide_Step_Settings_Help' => 'Elija qué tipos de pedido acepta, la sucursal cuyo stock usan las ventas del restaurante, el cargo por servicio, las propinas y el redondeo.',
'Rst_Guide_Step_Floor' => 'Zonas del comedor y mesas',
'Rst_Guide_Step_Floor_Ok' => '{areas} zonas, {tables} mesas.',
'Rst_Guide_Step_Floor_Help' => 'Añada sus zonas (Interior, Terraza…) y sus mesas con el número de asientos. "Añadir varias" crea T1–T20 de una vez.',
'Rst_Guide_Step_Stations' => 'Estaciones de cocina',
'Rst_Guide_Step_Stations_Ok' => '{n} estaciones.',
'Rst_Guide_Step_Stations_Help' => 'Las estaciones (Parrilla, Freidora, Fríos, Postres, Bebidas…) dividen la pantalla de cocina para que cada cocinero vea solo sus platos.',
'Rst_Guide_Step_Dishes' => 'Platos y complementos',
'Rst_Guide_Step_Dishes_Ok' => '{n} platos configurados, {groups} grupos de complementos.',
'Rst_Guide_Step_Dishes_Help' => 'Los platos son sus productos normales. En Restaurante › Menú asígneles una estación, un tiempo de preparación, etiquetas dietéticas y grupos de complementos (tamaños, extras).',
'Rst_Guide_Step_Payments' => 'Pagos',
'Rst_Guide_Step_Payments_Ok' => '{n} métodos de pago listos, con efectivo, y un cliente predeterminado para las cuentas sin cliente.',
'Rst_Guide_Step_Payments_Help' => 'Las cuentas necesitan al menos un método de pago activo, un método de efectivo (el cambio se da en efectivo) y un cliente predeterminado en Ajustes del sistema.',
'Rst_Guide_Step_Staff' => 'Permisos del personal',
'Rst_Guide_Step_Staff_Help' => 'Roles que pueden tomar pedidos: {waiters}; usar la pantalla de cocina: {kitchen}; cobrar: {cashiers}. Dé a cada rol solo lo que necesita ese puesto (vea "Quién hace qué").',
'Rst_Guide_Step_First' => 'Su primera cuenta',
'Rst_Guide_Step_First_Ok' => '{n} cuentas cobradas hasta ahora.',
'Rst_Guide_Step_First_Help' => 'Siente una mesa de prueba en el plano del salón, añada un plato, envíelo, márquelo como listo en la pantalla de cocina y cobre.',
'Rst_Guide_Step_Qr' => 'Pedidos en mesa por QR',
'Rst_Guide_Step_Qr_On' => 'Activado. {n} mesas tienen código QR.',
'Rst_Guide_Step_Qr_Help' => 'Los comensales escanean un código en la mesa, eligen platos en su teléfono y los envían al pedido de la mesa. Actívelo en Configuración del restaurante y luego imprima los códigos.',
'Rst_Guide_Step_Booking' => 'Reserva de mesa online',
'Rst_Guide_Step_Booking_On' => 'Activada. Las reservas de la tienda online llegan a Reservas para confirmarlas.',
'Rst_Guide_Step_Booking_Help' => 'Permita que los comensales reserven una mesa desde la tienda online. Defina el horario de reservas, el intervalo y el grupo más grande en Configuración del restaurante.',
'Rst_Guide_Step_Store' => 'Tienda online y tema Restaurante',
'Rst_Guide_Step_Store_On' => 'El tema Restaurante está activo. Los pedidos online llegan a la cocina: {mode}.',
'Rst_Guide_Step_Store_Help' => 'En Tienda online › Configuración elija el tema "Restaurante": la página de inicio se convierte en su menú, con complementos, recogida / entrega a domicilio y reserva de mesa.',
'Rst_Guide_How' => 'Cómo funciona',
'Rst_Guide_Service' => 'Un servicio, paso a paso',
'Rst_Guide_Service_1_T' => 'Sentar',
'Rst_Guide_Service_1' => 'En el plano del salón elija una mesa libre, introduzca el número de comensales y el camarero, y luego "Sentar a los comensales y tomar el pedido". Un grupo con reserva se sienta desde su reserva.',
'Rst_Guide_Service_2_T' => 'Pedir',
'Rst_Guide_Service_2' => 'Toque los platos en la pantalla del pedido. Elija complementos, asiento y tiempo; añada una nota para la cocina. Retenga un tiempo para enviarlo más tarde.',
'Rst_Guide_Service_3_T' => 'Enviar',
'Rst_Guide_Service_3' => '"Enviar" pone los platos nuevos en una sola comanda de cocina. Los platos aún no enviados se pueden cambiar o quitar; después solo se pueden anular indicando un motivo.',
'Rst_Guide_Service_4_T' => 'Cocinar',
'Rst_Guide_Service_4' => 'La pantalla de cocina muestra la comanda en cada estación. Los cocineros la empiezan, marcan los platos a medida que los terminan y la despachan cuando todo está listo.',
'Rst_Guide_Service_5_T' => 'Servir',
'Rst_Guide_Service_5' => 'Los platos listos aparecen en el plano del salón y en la pantalla del pedido. El camarero los lleva a la mesa y toca "Marcar como servidos".',
'Rst_Guide_Service_6_T' => 'Cobrar',
'Rst_Guide_Service_6' => '"Cuenta y pago" imprime la cuenta y cobra: cuenta completa, dividida a partes iguales o por artículo. Cada pago es una venta POS normal.',
'Rst_Guide_Service_7_T' => 'Liberar',
'Rst_Guide_Service_7' => 'Cuando todo está pagado, el pedido se cierra y la mesa pasa a "Por limpiar" (o directamente a libre, según la Configuración del restaurante).',
'Rst_Guide_Roles' => 'Quién hace qué',
'Rst_Guide_Roles_Help' => 'Los permisos del restaurante se asignan por rol en Permisos de grupo. Un usuario puede tener los permisos de varios roles.',
'Rst_Guide_Job' => 'Puesto',
'Rst_Guide_Give' => 'Asignar estos permisos',
'Rst_Guide_Job_Waiter' => 'Camarero',
'Rst_Guide_Job_Cook' => 'Cocinero',
'Rst_Guide_Job_Cashier' => 'Cajero',
'Rst_Guide_Job_Host' => 'Anfitrión / recepción',
'Rst_Guide_Job_Supervisor' => 'Supervisor',
'Rst_Guide_Job_Manager' => 'Gerente',
'Rst_Guide_Menu' => 'Menú, estaciones y complementos',
'Rst_Guide_Menu_1' => 'Cualquier producto que venda puede ser un plato. Restaurante › Menú (o la tarjeta "Detalles del plato" del formulario del producto) añade la información del restaurante.',
'Rst_Guide_Menu_2' => 'Los grupos de complementos contienen opciones con precio: "Tamaño" (elegir 1) o "Extras" (hasta 3). Las reglas se comprueban en cada pedido, también en los online.',
'Rst_Guide_Menu_3' => 'Un complemento puede consumir un ingrediente: vincule "Queso extra" a su producto Queso y cada uno descontará ese stock.',
'Rst_Guide_Menu_4' => 'Marque un plato como agotado por hoy con un solo interruptor; vuelve a estar disponible mañana automáticamente. Los horarios de comidas (desayuno, almuerzo, cena) limitan cuándo se ofrece un plato.',
'Rst_Guide_Menu_5' => 'Una receta es un producto combo: con el stock virtual de combos activado, vender el plato descuenta sus componentes del stock.',
'Rst_Guide_Kitchen' => 'Pantalla de cocina',
'Rst_Guide_Kitchen_1' => 'Abra Restaurante › Cocina en una pantalla de la cocina. Elija la estación; los platos sin estación aparecen en todas las estaciones.',
'Rst_Guide_Kitchen_2' => 'Las comandas se ponen ámbar y luego rojas mientras esperan (Configuración del restaurante › retrasada después de N minutos). Un pitido anuncia las comandas nuevas.',
'Rst_Guide_Kitchen_3' => 'Empezar → marcar platos → Despachar. "Terminada en esta estación" finaliza solo los platos de esta estación en una comanda compartida.',
'Rst_Guide_Kitchen_4' => 'Las comandas servidas permanecen 15 minutos para poder recuperar un error. Las comandas se pueden imprimir en una impresora de 80 mm.',
'Rst_Guide_Kitchen_5' => 'Los pedidos de la tienda online y de los códigos QR de mesa se marcan como "Online" o "QR" en su comanda.',
'Rst_Guide_Bills' => 'Cuentas y pagos',
'Rst_Guide_Bills_1' => 'Cada pago es una venta POS normal: el stock, la caja registradora, la contabilidad, los puntos de fidelidad y la facturación electrónica funcionan igual que en el POS.',
'Rst_Guide_Bills_2' => 'El cargo por servicio es un porcentaje de los platos antes de impuestos, para pedidos en el local (o para todos los pedidos, según su configuración). Las propinas son un porcentaje predefinido o un importe.',
'Rst_Guide_Bills_3' => 'Un descuento requiere el permiso "Descuentos del restaurante" y está limitado por el descuento máximo de la Configuración del restaurante.',
'Rst_Guide_Bills_4' => 'El redondeo se hace hacia abajo según su múltiplo, a favor del cliente, en el pago que liquida la cuenta.',
'Rst_Guide_Bills_5' => 'Dividir a partes iguales: una venta, una línea de pago por persona (partes al céntimo). Dividir por artículo: los platos de cada comensal se convierten en su propia venta; elija un asiento para seleccionar sus platos.',
'Rst_Guide_Bills_6' => 'Si la cuenta cambió después de mostrarse (un plato añadido desde un código QR, una propina modificada), el pago se rechaza para que nunca se cobre al cliente algo que no ha visto.',
'Rst_Guide_Bills_7' => 'Los platos pagados no se pueden anular. Si se anula el resto no pagado de un pedido, el pedido se cierra como pagado y la mesa se puede liberar.',
'Rst_Guide_Bookings' => 'Reservas y lista de espera',
'Rst_Guide_Bookings_1' => 'Las reservas guardan una mesa durante su duración (predeterminada en Configuración del restaurante). Dos reservas nunca pueden solaparse en una mesa.',
'Rst_Guide_Bookings_2' => 'El plano del salón muestra la próxima reserva de cada mesa y avisa cuando está cerca; "Ya llegaron — sentar" sienta al grupo.',
'Rst_Guide_Bookings_3' => 'Pasado el tiempo de no presentación, un grupo que llega tarde puede marcarse como no presentado; un error se puede restaurar.',
'Rst_Guide_Bookings_4' => 'La lista de espera mantiene en orden a los clientes sin reserva con su espera estimada. Llámelos o escríbales por WhatsApp cuando haya una mesa lista y luego siéntelos.',
'Rst_Guide_Bookings_5' => 'Las reservas online llegan como "Reservado" (una insignia en la barra lateral las cuenta) para que usted las confirme.',
'Rst_Guide_Online' => 'Pedidos online, menús QR y reserva online',
'Rst_Guide_Online_1' => 'Con el tema de tienda Restaurante, la página de inicio de la tienda online es su menú, con complementos y filtros dietéticos; los clientes pagan en el proceso de pago como siempre.',
'Rst_Guide_Online_2' => '"Los pedidos online van a la cocina" decide cuándo llegan a la pantalla de cocina: al realizarse (pagados, o de un cliente con sesión iniciada que paga a la entrega / al recoger), al aceptarse, o nunca.',
'Rst_Guide_Online_3' => 'Los códigos QR de mesa (Configuración del salón › Códigos QR de las mesas) abren el menú de esa mesa. "Nuevo enlace" invalida un código impreso.',
'Rst_Guide_Online_4' => 'Los pedidos por QR esperan en el pedido de la mesa a que un camarero los envíe, salvo que esté activado "Enviar los pedidos por QR directamente a la cocina". Los comensales pagan al personal.',
'Rst_Guide_Online_5' => 'La reserva online solo ofrece horas en las que una mesa adecuada para el grupo está libre durante toda la reserva, y limita cada número de teléfono a 3 reservas próximas.',
'Rst_Guide_Online_6' => 'Todo esto forma parte de la tienda online: debe estar activada e incluida en su plan.',
'Rst_Guide_Reports' => 'Panel e informes',
'Rst_Guide_Reports_1' => 'El panel compara hoy con el mismo día de la semana pasada: ventas, cuentas, comensales, cuenta media, anulaciones y descuentos, además de lo que está pasando ahora mismo.',
'Rst_Guide_Reports_2' => 'Las ventas son las cuentas del restaurante más los pedidos online que llegaron a la cocina. Las ventas y los márgenes de los platos son antes de impuestos y usan el costo de cada producto.',
'Rst_Guide_Reports_3' => 'Informes: ventas por día y método de pago, platos, anulaciones y cancelaciones (con motivos), personal, tiempos de cocina y reservas — cada uno se exporta a Excel.',
'Rst_Guide_Reports_4' => 'El personal limitado a algunas sucursales solo ve sus sucursales; los pedidos sin sucursal los comparten todos.',
'Rst_Guide_Faq' => 'Conviene saber',
'Rst_Guide_Faq_1_Q' => 'Un pedido para llevar se pagó antes de pulsar "Enviar". ¿Se cocinará?',
'Rst_Guide_Faq_1_A' => 'Sí. Al cobrar se envían a la cocina los platos que aún no se habían enviado.',
'Rst_Guide_Faq_2_Q' => '¿Por qué no puedo liberar una mesa?',
'Rst_Guide_Faq_2_A' => 'Su pedido todavía tiene platos sin pagar. Cobre, anule lo que no se consumió o cancele el pedido (solo si aún no se ha pagado nada).',
'Rst_Guide_Faq_3_Q' => 'Se juntaron dos mesas. ¿Qué pasa con sus pedidos?',
'Rst_Guide_Faq_3_A' => '"Unir mesas" pasa los platos de la segunda mesa (y cualquier pago) al pedido de la mesa principal; "Separar esta mesa" vuelve a separar las mesas.',
'Rst_Guide_Faq_4_Q' => '¿Se pueden usar pagos con tarjeta de Stripe aquí?',
'Rst_Guide_Faq_4_A' => 'No. Los pagos con tarjeta de Stripe necesitan el formulario de tarjeta del POS; para un terminal de tarjetas añada un método de pago como "Tarjeta" y úselo en la cuenta.',
'Rst_Guide_Faq_5_Q' => 'Un plato no tiene stock solo en una sucursal.',
'Rst_Guide_Faq_5_A' => 'El stock se toma de la sucursal del pedido (la zona de la mesa o, si no, la sucursal predeterminada de la Configuración del restaurante). Use "Agotado hoy" para detener los pedidos rápidamente.',
'Rst_Guide_Faq_6_Q' => '¿Necesito una impresora?',
'Rst_Guide_Faq_6_A' => 'No. Las cuentas, los recibos y las comandas de cocina se imprimen desde el navegador en cualquier impresora; las impresoras de recibos de 80 mm son las más adecuadas.',
'Rst_Guide_Faq_7_Q' => '¿De dónde salen los menús del restaurante en la tienda online?',
'Rst_Guide_Faq_7_A' => 'De los mismos productos, categorías y complementos. Los productos ocultos en la tienda online y las categorías que no se muestran en la tienda quedan fuera del menú online y del menú QR.',

