'Bkm_Guide_Faq' => 'Preguntas',
'Bkm_Guide_Faq_1_Q' => '¿Por qué un servicio no aparece en el sitio web?',
'Bkm_Guide_Faq_1_A' => 'Necesita detalles de reserva (Servicios), "Mostrar en el sitio web" activado, el producto activo y, para elegir una hora, alguien reservable en línea que lo realice.',
'Bkm_Guide_Faq_2_Q' => '¿Por qué no hay horas libres?',
'Bkm_Guide_Faq_2_A' => 'Revise el horario laboral del personal, los días libres, los días festivos y las ausencias aprobadas, la antelación mínima y con cuántos días de antelación pueden reservar los clientes.',
'Bkm_Guide_Faq_3_Q' => '¿Pueden dos clientes reservar la misma hora?',
'Bkm_Guide_Faq_3_A' => 'No. La hora se vuelve a comprobar al reservar, y una reserva retenida o confirmada la bloquea. Las clases comparten plazas hasta su límite.',
'Bkm_Guide_Faq_4_Q' => '¿Qué ocurre cuando vence una retención?',
'Bkm_Guide_Faq_4_A' => 'La hora vuelve a estar libre para otros. La reserva se mantiene en Solicitudes hasta que usted la responda (o se cancela si su depósito no se pagó).',
'Bkm_Guide_Faq_5_Q' => '¿Los clientes necesitan una cuenta?',
'Bkm_Guide_Faq_5_A' => 'No. Reciben un enlace privado a su página de reserva. Las cuentas de la tienda y del portal también muestran sus reservas.',
'Bkm_Guide_Faq_6_Q' => '¿Adónde va el dinero?',
'Bkm_Guide_Faq_6_A' => 'Los depósitos van a su proveedor de pagos; el resto se cobra en el POS cuando usted cobra la reserva. Los informes cuentan los ingresos de esas ventas.',
'Bkm_Guide_Faq_7_Q' => '¿Por qué un cliente no recibió un correo?',
'Bkm_Guide_Faq_7_A' => 'Abra la reserva: su lista de mensajes indica si cada correo se envió, falló o se omitió, y por qué.',
