'Mkg_Guide_Faq' => 'Preguntas frecuentes',
'Mkg_Guide_Faq_1_Q' => 'Mi campaña sigue en Enviando y no sale nada.',
'Mkg_Guide_Faq_1_A' => 'El proceso de envío en segundo plano no la ha recogido. Tras 30 minutos sin avances vuelve a aparecer el botón Enviar ahora: haga clic en él para reanudarla. Si sigue ocurriendo, pida al administrador de la plataforma que compruebe que las tareas en segundo plano (el queue worker) se están ejecutando.',
'Mkg_Guide_Faq_2_Q' => 'Los destinatarios muestran "Omitido: canal de correo electrónico desactivado".',
'Mkg_Guide_Faq_2_A' => 'Active Activar correo electrónico en Configuración de marketing y vuelva a enviar la campaña.',
'Mkg_Guide_Faq_3_Q' => 'Los destinatarios muestran "No hay servidor de correo configurado".',
'Mkg_Guide_Faq_3_A' => 'Las campañas de correo electrónico solo se envían a través de su propio servidor de correo. Agréguelo en Configuración > Configuración de correo.',
'Mkg_Guide_Faq_4_Q' => 'El mensaje llegó a menos personas de las que hay en mi segmento.',
'Mkg_Guide_Faq_4_A' => 'Se omiten los clientes sin dirección de correo electrónico (Correo electrónico) o número de teléfono (SMS, WhatsApp). Abra la campaña para ver a quién se omitió y por qué.',
'Mkg_Guide_Faq_5_Q' => '¿Enviado significa que el cliente lo recibió?',
'Mkg_Guide_Faq_5_A' => 'Enviado significa que su servidor de correo o pasarela aceptó el mensaje. No se hace seguimiento de la entrega en la bandeja de entrada, las aperturas ni el filtrado de spam.',
'Mkg_Guide_Faq_6_Q' => '¿Puedo editar una campaña después de enviarla?',
'Mkg_Guide_Faq_6_A' => 'No. Las campañas en envío y enviadas quedan bloqueadas; cree una campaña nueva en su lugar.',
'Mkg_Guide_Faq_7_Q' => 'Mis mensajes de WhatsApp no llegan.',
'Mkg_Guide_Faq_7_A' => 'Pasadas 24 horas desde que un cliente le escribió por última vez, WhatsApp solo entrega plantillas aprobadas por Meta. Use la WhatsApp Cloud API y elija una plantilla aprobada en la campaña.',
'Mkg_Guide_Faq_8_Q' => 'Si vuelvo a enviar una campaña, ¿la recibirán los clientes dos veces?',
'Mkg_Guide_Faq_8_A' => 'Reanudar una campaña detenida solo envía a los destinatarios que siguen pendientes, por lo que nadie que ya la recibió vuelve a recibirla. Volver a enviar una campaña fallida empieza de nuevo con una lista nueva.',

