'Pd_Guide_How_Title' => 'Cómo funciona',
'Pd_Guide_How_Intro' => 'Un dispositivo POS es un terminal de tarjetas o una caja registradora fiscal junto a la caja. Stocky le envía el importe, espera a que el cliente pague y registra el pago solo después de que el dispositivo lo aprueba.',
'Pd_Guide_Step_1' => 'Agregue aquí el dispositivo: modelo, almacén y el método de pago con el que se registran sus pagos con tarjeta (por ejemplo, "Tarjeta de crédito").',
'Pd_Guide_Step_2' => 'Elija cómo se comunica Stocky con él: un puente local en el equipo del cajero o la API en la nube de su proveedor. Introduzca los ID y las claves de su banco o proveedor.',
'Pd_Guide_Step_3' => 'Pulse Probar conexión. Los dispositivos con puente deben probarse desde el equipo del cajero en el que se ejecuta el puente.',
'Pd_Guide_Step_4' => 'En el POS, elija ese método de pago, pulse "Cobrar en el dispositivo" y deje que el cliente pague. La venta se puede completar en cuanto el dispositivo la aprueba.',
'Pd_Guide_Step_5' => 'Revise Transacciones para encontrar pagos con tarjeta cobrados sin venta (por ejemplo, un cobro abandonado) y anúlelos o reembólselos.',
'Pd_Guide_Bridge_Text' => 'Para dispositivos controlados por el SDK de un fabricante en el equipo del cajero (USB, serie o emparejamiento por LAN). El navegador no puede usar el SDK directamente, así que un pequeño programa puente lo envuelve y escucha en este equipo.',
'Pd_Guide_Bridge_Point_1' => 'El POS envía cada solicitud a la URL del puente desde el navegador del cajero; el servidor de Stocky nunca necesita acceder a la red de su tienda.',
'Pd_Guide_Bridge_Point_2' => 'Las solicitudes y respuestas se firman con el secreto compartido, por lo que no se puede falsificar una aprobación desde el navegador.',
'Pd_Guide_Bridge_Point_3' => 'Instale e inicie el puente en cada equipo que cobre pagos con tarjeta en este dispositivo.',
'Pd_Guide_Cloud_Text' => 'Para proveedores que acceden al dispositivo por internet. El servidor de Stocky llama a la API, así que no hay que instalar nada en el equipo del cajero.',
'Pd_Guide_Cloud_Point_1' => 'La URL de la API debe ser https:// en una dirección pública.',
'Pd_Guide_Cloud_Point_2' => 'Mientras el cliente paga, Stocky consulta el estado cada 2 segundos, por lo que el endpoint de estado debe reconocer el pago por su referencia; si la API responde antes de que termine la operación con la tarjeta ("pending"), decide la consulta periódica.',
'Pd_Guide_Ide280_Title' => 'Ingenico IDE280',
'Pd_Guide_Ide280_Text' => 'El IDE280 es una caja registradora fiscal de nueva generación (YN ÖKC) con lector de tarjetas. Normalmente se integra mediante el SDK ECR / GMP3 de Ingenico o mediante el servicio de integración de su banco.',
'Pd_Guide_Ide280_Point_1' => 'Empareje el dispositivo con el equipo del cajero como se describe en la documentación de Ingenico / del banco y luego apunte el puente (o la configuración de la API) hacia él.',
'Pd_Guide_Ide280_Point_2' => 'Los importes se envían tanto en decimales como en kuruş (amount_minor), con la moneda TRY / 949.',
'Pd_Guide_Ide280_Point_3' => 'Con "Recibo fiscal completo", cada artículo lleva el departamento del dispositivo correspondiente a su tipo de IVA: haga coincidir los departamentos de IVA con la programación del dispositivo.',
'Pd_Guide_Protocol_Title' => 'Contrato del puente / API',
'Pd_Guide_Protocol_Intro' => 'Stocky se comunica en JSON con el puente o la API. Las rutas siguientes son las predeterminadas y se pueden cambiar por dispositivo en Avanzado.',
'Pd_Guide_Operation' => 'Operación',
