'Pd_Guide_When_Sale' => 'El cajero pulsa "Cobrar en el dispositivo". Puede responder cuando termina la operación con la tarjeta o de inmediato con el estado "pending".',
'Pd_Guide_When_Status' => 'Cada 2 segundos mientras el pago está pendiente.',
'Pd_Guide_When_Cancel' => 'El cajero cancela mientras espera la tarjeta.',
'Pd_Guide_When_Void' => 'Anulación de un pago (mismo día, importe completo).',
'Pd_Guide_When_Refund' => 'Reembolso de una parte o de todo un pago.',
'Pd_Guide_Request_Title' => 'Solicitud',
'Pd_Guide_Request_Text' => 'El cuerpo que Stocky envía para una venta. El reembolso y la anulación incluyen el pago original como "original".',
'Pd_Guide_Response_Title' => 'Respuesta',
'Pd_Guide_Response_Text' => 'Los nombres de campo se leen con flexibilidad (también dentro de "data"); "status" o response_code "00" determinan el resultado. Los números de tarjeta se guardan enmascarados.',
'Pd_Guide_Signing_Title' => 'Firma (puente)',
'Pd_Guide_Signing_Text' => 'El puente debe verificar la firma de Stocky, y debe firmar el cuerpo exacto de su respuesta y devolver tanto "reference" como "operation": las respuestas sin firmar, o sobre otra operación, se rechazan.',
'Pd_Guide_Browser_Title' => 'Acceso desde el navegador (puente)',
'Pd_Guide_Browser_Text' => 'La página del POS llama al puente desde el navegador, por lo que el puente debe responder con estos encabezados CORS (incluida la solicitud previa OPTIONS).',
'Pd_Guide_Safety_Title' => 'Conviene saber',
'Pd_Guide_Safety_1' => 'Una venta solo se guarda con un pago del dispositivo aprobado por el mismo importe; un pago del dispositivo nunca puede pagar dos ventas.',
'Pd_Guide_Safety_2' => 'Cerrar la ventana de pago después de cobrar una tarjeta anula primero ese cobro.',
'Pd_Guide_Safety_3' => 'Si el dispositivo no responde a tiempo, el pago aparece como "Sin respuesta": revise el dispositivo y anule el cobro desde Transacciones si se cobró la tarjeta.',
'Pd_Guide_Safety_4' => 'Los reembolsos y anulaciones de aquí solo mueven dinero en la tarjeta; no modifican la venta. Registre la mercancía devuelta en Devoluciones de ventas.',
'Perm_Pos_Terminals_Manage' => 'Dispositivos POS: gestionar, reembolsar y anular',
