'Pd_Lost_Track' => 'Se perdió el contacto antes de que el dispositivo respondiera. Revise el dispositivo y pulse "Comprobar de nuevo"; no vuelva a cobrar hasta saber qué pasó.',
'Pd_Close_Anyway' => 'No se pudo anular el pago con tarjeta. ¿Cerrar de todos modos? Queda en Dispositivos POS › Transacciones como "Cobrado sin venta" para que pueda anularse o reembolsarse allí.',
