'Count_Upload' => 'Cargar conteo',
'Count_Upload_Help' => 'Cargue las cantidades contadas en un archivo con una columna Code y una columna Counted (la hoja de conteo de esta página sirve tal cual). Cada diferencia se calcula frente al inventario en el momento de aplicarla y se registra como un único ajuste "Conteo de inventario". Las filas con la celda Counted en blanco no se modifican.',
