'Product_Code_Numbering_Help' => 'Si se configura, "Generar" en el formulario de producto crea prefijo + número (p. ej. STK-1001) y omite los números ya usados, para que los códigos nunca coincidan con los de otro sistema. Deje ambos vacíos para obtener códigos aleatorios. Los códigos EAN / UPC siguen siendo numéricos.',
