'Api_Title' => 'API',
'Api_Keys' => 'Claves',
'Api_Not_Ready' => 'La API aún no está configurada: ejecute primero la actualización de la base de datos.',
'Api_Keys_Help' => 'Las claves permiten que otro sistema (un ERP, una tienda en línea, su propio catálogo) lea y actualice Stocky directamente. Una clave actúa en su nombre: puede hacer lo que permite su rol, en sus almacenes. Una clave de solo lectura solo puede leer. Revoque una clave de inmediato si cree que pudo filtrarse.',
'Api_New_Key' => 'Nueva clave',
