'Api_Revoke_Confirm' => '¿Revocar esta clave? Los sistemas que la usan dejarán de funcionar de inmediato.',
'Api_Reference' => 'Referencia',
'Api_Doc_Intro' => 'Una API REST en JSON. Envíe la clave en cada llamada; las listas se paginan con page y per_page y devuelven data y meta. Los productos se buscan por código de producto, código de variante o código de barras adicional.',
'Api_Base_Url' => 'URL base',
'Api_Auth' => 'Autenticación',
'Api_Limits' => 'Límite de solicitudes',
'Api_Limits_Text' => '120 llamadas por minuto por usuario de la clave; HTTP 429 si se supera.',
'Api_Idempotency_Text' => 'Opcional en las llamadas de escritura: una cadena única por operación de negocio. Un reintento con la misma clave devuelve la primera respuesta correcta en lugar de registrar dos veces; tras un error, corrija la solicitud y reintente con la misma clave.',
'Api_Params' => 'Parámetros',
'Api_Errors' => 'Errores',
'Api_Webhooks_Hint' => 'Para recibir avisos cuando se complete una venta o devolución, agregue un webhook en Integraciones > Webhooks: los eventos de venta y devolución ahora incluyen sus líneas de producto.',
'Api_Name_Placeholder' => 'p. ej. Sincronización del catálogo',
