'Api_Ep_Upsert' => 'Crear o actualizar un producto por código',
'Api_Ep_Upsert_Notes' => 'Un código desconocido crea un producto estándar (se requieren nombre, categoría, unidad, costo y precio). Un código conocido actualiza solo los campos que envíe. Un código de variante actualiza los precios de esa variante. barcodes reemplaza la lista de códigos de barras adicionales.',
'Api_Ep_Stock' => 'Niveles de inventario',
'Api_Ep_Adjust' => 'Registrar un ajuste de inventario',
'Api_Ep_Adjust_Notes' => 'Las cantidades positivas agregan inventario y las negativas lo retiran. Se crea un único ajuste, anotado con el motivo y la referencia; elimínelo en la aplicación para deshacerlo.',
'Api_Ep_Purchase' => 'Crear una compra',
'Api_Ep_Purchase_Notes' => 'Cantidades en unidades de compra; si falta el costo se usa el costo actual del producto. Una compra recibida agrega inventario de inmediato. La misma referencia de factura de proveedor dos veces se rechaza, salvo que allow_duplicate_reference sea true.',
'Api_Ep_Sales' => 'Líneas de venta desde una fecha',
