'Cd_Title' => 'Dominio personalizado',
'Cd_Intro' => 'Use su propio dominio para este espacio de trabajo en lugar del subdominio de la plataforma. Agregue el dominio, cree el registro DNS en su proveedor de dominio y luego compruebe el DNS.',
