'Cd_Added' => 'Dominio agregado. Cree el registro DNS y luego compruebe el DNS.',
'Cd_Dns_Title' => 'Configuración de DNS',
'Cd_Dns_Intro' => 'Cree UNO de estos registros en su proveedor de dominio y luego haga clic en Comprobar DNS. Los cambios suelen tardar unos minutos, y hasta 48 horas, en propagarse.',
'Cd_Dns_Type' => 'Tipo',
'Cd_Dns_Host' => 'Host / Nombre',
'Cd_Dns_Value' => 'Valor / Apunta a',
'Cd_Dns_Cname_Note' => 'Recomendado para subdominios.',
'Cd_Dns_A_Note' => 'Úselo cuando no sea posible un CNAME (dominios raíz).',
'Cd_Dns_Txt_Note' => 'Demuestra la propiedad mientras el registro CNAME o A aún se está propagando.',
'Cd_Dns_Ip_Unknown' => 'Solicite la IP del servidor al administrador de la plataforma.',
'Cd_Ssl_Hint' => 'Tras la verificación, el equipo de la plataforma instala el certificado HTTPS para su dominio. La insignia SSL pasa a activa por sí sola cuando el candado funciona (se comprueba cada hora y cada vez que hace clic en Verificar). Si después de un día sigue mostrando fallido, contacte con soporte.',
'Cd_Err_invalid' => 'Introduzca un nombre de dominio válido, como shop.example.com.',
'Cd_Err_is_central' => 'Este es un dominio reservado de la plataforma.',
'Cd_Err_duplicate' => 'Este dominio ya está en uso.',
'Cd_Err_limit_reached' => 'Ha alcanzado el número de dominios personalizados que permite su plan.',
'Cd_Err_not_verified' => 'Verifique el dominio antes de establecerlo como principal.',
'Cd_Err_no_records' => 'Aún no se han encontrado registros DNS. La propagación puede tardar unos minutos.',
'Cd_Err_mismatch' => 'Se encontraron registros DNS, pero no apuntan a este servidor.',
'Cd_Err_lookup_failed' => 'La consulta DNS falló. Inténtelo de nuevo en un momento.',
'Cd_Err_unknown' => 'La verificación falló. Revise la configuración DNS.',
'Cd_Found_Records' => 'Registros encontrados',
'Cd_Guide_Title' => 'Cómo funciona',
'Cd_Guide_1' => 'Añada el dominio que posee, por ejemplo shop.example.com.',
'Cd_Guide_2' => 'Inicie sesión en su proveedor de dominios (GoDaddy, Namecheap, Cloudflare...) y cree el registro DNS indicado.',
'Cd_Guide_3' => 'Vuelva aquí y haga clic en Comprobar DNS. Una vez verificado, su espacio de trabajo, su tienda en línea y su portal de clientes responderán en ese dominio.',
'Cd_Guide_4' => 'El subdominio de la plataforma sigue funcionando junto con el dominio personalizado.',
'Cd_Cloudflare_Note' => 'Usuarios de Cloudflare: configuren el registro como DNS only (nube gris) hasta que finalice la verificación.',
'Perm_custom_domains' => 'Dominio personalizado (Configuración > Dominio personalizado)',
'List_Too_Big_All' => 'Esta lista tiene más de {count} filas, por lo que la opción Todos está desactivada. Se muestran 100 filas por página. Use la búsqueda o los filtros para acotarla.',
'List_Too_Big_Export' => 'Esta lista tiene más de {count} filas, demasiadas para exportarlas de una vez. Use la búsqueda o los filtros para acotarla.',
'PartiallyPaid' => 'Pagado parcialmente',
'Ord_Guide_PayAuto_Tip' => 'Se actualiza automáticamente cuando se registran pagos en la venta. Haga clic para ver cómo registrar un pago.',
'Ord_Guide_PayAuto_Intro' => 'Esta columna muestra cuánto del pedido se ha pagado. Parte de la opción elegida por el cliente al finalizar la compra y luego se actualiza automáticamente a medida que se registran pagos en la venta que se crea al confirmar el pedido. No se puede editar desde esta página.',
'Ord_Guide_PayAuto_Paid' => 'Se ha recibido el importe total. Si el cliente pagó en línea mediante una pasarela de pago, al confirmar el pedido se crea la venta como Pagada y se registra el pago por usted. De lo contrario, el estado cambia a Pagado cuando los pagos de la venta cubren el total.',
'Ord_Guide_PayAuto_Partial' => 'Se ha registrado un pago en la venta, pero parte del total sigue pendiente.',
'Ord_Guide_PayAuto_Pending' => 'Aún no se ha recibido ningún pago: pago contra entrega, transferencia bancaria u otro método de pago posterior. Al confirmar el pedido, la venta se crea como No pagada, por lo que usted mismo registra el dinero cuando lo cobre. Consulte los pasos a continuación.',
'Ord_Guide_PayAuto_Note' => 'El estado de pago que se muestra aquí sigue a la venta: cambia a Pagado parcialmente o Pagado automáticamente al guardar un pago, y vuelve atrás si elimina uno. La venta es el registro contable y es la que alimenta sus informes de pagos y de beneficios. Use Mostrar pagos en la venta para revisar o editar lo que introdujo.',
'Ord_LinkedSale' => 'Venta vinculada',
'Ord_LinkedSale_Missing' => 'No hay ninguna venta vinculada a este pedido. Es posible que la venta se haya eliminado o que el pedido se confirmara antes de que los pedidos se vincularan a las ventas.',
'Sale_FromOnlineOrder' => 'Esta venta se creó a partir del pedido en línea',
'Mod_Opencart_Desc' => 'Sincronización con la tienda OpenCart: productos, stock y pedidos.',
'Int_Desc_Opencart' => 'Sincronice productos, variantes, stock y pedidos con su tienda OpenCart.',
'Perm_opencart_settings' => 'Integración con OpenCart',
'Oc_Hero_Desc' => 'Sincronice productos, variantes, stock y pedidos con su tienda OpenCart mediante el {company} Connector.',
'Oc_Connector' => '{company} Connector',
'Oc_Download_Connector' => 'Descargar para OpenCart 4',
'Oc_Connector_Help' => 'OpenCart no tiene API para productos ni stock, así que primero se instala esta pequeña extensión en su tienda.',
'Oc_Secret' => 'Secreto del conector',
'Oc_Secret_Placeholder' => 'Desde el módulo {company} Connector',
'Oc_Secret_Help' => 'Abra el módulo {company} Connector en OpenCart y copie aquí su secreto. Se guarda cifrado y no se vuelve a mostrar.',
'Oc_Store' => 'Tienda OpenCart',
'Oc_Versions' => 'Conector {connector} en OpenCart {opencart}',
'Oc_Automation' => 'Automatización',
'Oc_Auto_Orders' => 'Importar pedidos automáticamente',
'Oc_Auto_Orders_Help' => 'Los pedidos nuevos y los cambios de estado llegan en el momento, con una comprobación cada pocos minutos de lo que se haya pasado por alto.',
'Oc_Auto_Stock' => 'Enviar stock automáticamente',
'Oc_Auto_Stock_Help' => 'Cada movimiento de stock actualiza la tienda, y todo el stock se comprueba una vez por hora.',
'Oc_Auto_Products' => 'Enviar cambios de productos automáticamente',
'Oc_Auto_Products_Help' => 'Un producto creado o editado aquí actualiza la tienda: nombre, precio, estado y stock.',
'Oc_Order_Statuses' => 'Estados de pedido',
'Oc_Order_Statuses_Help' => 'Qué significa aquí cada estado de OpenCart. Se configuraron a partir de su tienda y solo hay que cambiarlos si usa estados personalizados.',
'Oc_Commit_Statuses' => 'Venta completada',
'Oc_Commit_Statuses_Help' => 'La venta se completa y se descuenta el stock. Manténgalo igual que los estados que restan stock en OpenCart.',
'Oc_Paid_Statuses' => 'Pagado',
'Oc_Paid_Statuses_Help' => 'Se registra un pago por lo que aún está pendiente.',
'Oc_Cancel_Statuses' => 'Cancelado',
'Oc_Cancel_Statuses_Help' => 'La venta se revierte: el stock se repone y sus pagos se eliminan.',
'Oc_Variants_Linked' => 'Variantes vinculadas',
'Oc_Push_Desc' => 'Crea en OpenCart los productos y variantes que faltan, y actualiza nombre, precio, estado y stock de los vinculados. Las descripciones, imágenes y categorías solo se establecen cuando un producto es nuevo o no las tiene, de modo que los textos escritos en OpenCart se conservan.',
'Oc_Pull_Desc' => 'Importa los productos de OpenCart, emparejando los existentes por modelo o SKU y creando el resto. Los productos vinculados toman el nombre y el precio de OpenCart.',
'Oc_Pull_Stock' => 'Usar las cantidades de OpenCart como stock inicial de los productos nuevos',
'Oc_Reset_Confirm' => '¿Restablecer los vínculos de productos? El historial de pedidos conserva sus vínculos.',
'Oc_Stock_Desc' => 'Establece la cantidad en tienda de cada producto y variante vinculados según el stock que hay aquí.',
'Oc_Orders_Desc' => 'Importa los pedidos de la tienda como ventas (referencias como {ref}). En los pedidos ya importados solo se actualizan el estado y el pago, por lo que volver a importarlos es seguro.',
'Oc_Orders_Since' => 'Pedidos desde',
'Oc_Guide_1' => 'En la pestaña Conexión, descargue el {company} Connector.',
'Oc_Guide_2' => 'En el panel de administración de OpenCart, suba el archivo en {installer} y haga clic en Install; después instale el módulo en {modules}.',
'Oc_Guide_3' => 'Abra el módulo {name} y copie la URL de la tienda y el secreto.',
'Oc_Guide_4' => 'Péguelos en la pestaña Conexión, guarde y ejecute {test}. Esto también indica a la tienda adónde enviar los pedidos nuevos.',
'Oc_Guide_5' => 'Configure los productos: impórtelos si la tienda ya tiene un catálogo, envíelos si lo tiene {company}. Hágalo antes de confiar en el stock automático, porque {company} pasa a ser la fuente de las cifras de stock.',
'Oc_Guide_6' => 'Importe una vez los pedidos recientes si desea tener historial. A partir de entonces, los pedidos llegan solos.',
'Oc_Identity_Title' => 'Los productos se emparejan por modelo y SKU',
'Oc_Identity_Desc' => 'El código de producto de aquí se empareja con el modelo y el SKU de OpenCart. Manténgalos iguales en ambos lados. El stock de aquí es la cifra maestra: la tienda se actualiza a partir de él después de cada pedido.',
'Oc_Options_Title' => 'Opciones sin variantes',
'Oc_Options_Desc' => 'Las variantes de OpenCart tienen su propio stock y se corresponden con las variantes de aquí. Un producto que solo tiene opciones, sin variantes creadas, se importa como un único producto y su stock no se divide por opción.',
'Oc_Cancel_Title' => 'Pedidos cancelados',
'Oc_Cancel_Desc' => 'Cancelar un pedido en OpenCart revierte su venta aquí. Si la venta ya se entregó o tiene una devolución, no se deshace nada: la venta se marca en sus notas y en los registros para que usted la revise.',
'Oc_Download_Connector_3' => 'Descargar para OpenCart 3',
'Oc_Opencart3_Title' => 'Tiendas OpenCart 3',
'Oc_Opencart3_Desc' => 'OpenCart 3 no tiene variantes propias, solo opciones. Un producto con una opción (por ejemplo, Talla) se sincroniza con stock por valor de opción, que se corresponde con las variantes de aquí. Un producto con varias opciones recibe sus opciones creadas sin stock por combinación: su stock se lleva en el producto en su conjunto, y sus líneas de venta entran contra el producto.',
'Oc_G_Title' => 'Guía de OpenCart',
'Oc_G_Open_Settings' => 'Abrir la configuración de OpenCart',
'Oc_G_Your_Setup' => 'Su configuración',
'Oc_G_Your_Setup_Help' => 'En qué punto está este espacio de trabajo. Los pasos se actualizan a medida que avanza.',
'Oc_G_Step_Install' => 'Instalar el {company} Connector en su tienda',
'Oc_G_Step_Install_Help' => 'Una pequeña extensión que da a {company} acceso a productos, stock y pedidos. OpenCart no tiene API propia para ellos.',
'Oc_G_Step_Connect' => 'Conectar la tienda',
'Oc_G_Step_Connect_Help' => 'Pegue la URL de la tienda y el secreto de la página del módulo en la pestaña Conexión, guarde y ejecute Probar conexión.',
'Oc_G_Step_Connect_Done' => 'Conectado: conector {connector} en OpenCart {opencart}.',
'Oc_G_Step_Enable' => 'Activar la sincronización',
'Oc_G_Step_Enable_Help' => 'No se mueve nada mientras la integración está desactivada; los webhooks de la tienda se acusan y se ignoran.',
'Oc_G_Step_Products' => 'Vincular los productos',
'Oc_G_Step_Products_Help' => 'Importe el catálogo de la tienda o envíe el suyo, para que todos los productos de ambos lados estén vinculados antes de que empiece a fluir el stock.',
'Oc_G_Step_Products_Done' => '{n} productos y {v} variantes vinculados.',
'Oc_G_Step_Orders' => 'Recibir pedidos',
'Oc_G_Step_Orders_Help' => 'Una vez conectada, los pedidos nuevos llegan solos. Haga un pedido de prueba en la tienda para verlo aparecer en Ventas.',
'Oc_G_Step_Orders_No_Webhook' => 'Se importaron pedidos, pero todavía no ha llegado ninguno mediante el aviso de la tienda. Si la tienda no puede acceder a esta dirección, los pedidos siguen llegando con la comprobación que se realiza cada pocos minutos.',
'Oc_G_Step_Orders_Done' => 'La tienda está enviando avisos de pedidos.',
'Oc_G_Install_Title' => 'Instalar el conector',
'Oc_G_Install_Intro' => 'Elija su versión de OpenCart. El conector se instala con el propio instalador de extensiones de OpenCart; no se edita ningún archivo a mano.',
'Oc_G_Opencart_4' => 'OpenCart 4.x',
'Oc_G_Opencart_3' => 'OpenCart 3.x',
'Oc_G_I4_1' => 'Descargue el conector para OpenCart 4.',
'Oc_G_I4_2' => 'En el panel de administración de OpenCart, abra {path}, suba el archivo y haga clic en Install junto a él.',
'Oc_G_I4_3' => 'Abra {path}, busque {name} y haga clic en Install y luego en Edit.',
'Oc_G_I3_1' => 'Descargue el conector para OpenCart 3.',
'Oc_G_I3_2' => 'En el panel de administración de OpenCart, abra {path}, suba el archivo y espere a que terminen los pasos.',
'Oc_G_I3_3' => 'Abra {path}, busque {name} y haga clic en Install y luego en Edit.',
'Oc_G_I_4' => 'La página del módulo muestra la URL de la tienda y un secreto. Copie ambos.',
'Oc_G_I_5' => 'De vuelta aquí, péguelos en la pestaña Conexión, guarde y ejecute {test}. Esto también indica a la tienda adónde enviar los avisos de pedidos.',
'Oc_G_Requirements' => 'Qué necesita la tienda',
'Oc_G_Requirements_Desc' => 'OpenCart 3.0 o 4.0 y posteriores, PHP con cURL (estándar en cualquier hosting) y una dirección de tienda accesible desde Internet. Si la tienda está en una red privada, los pedidos siguen llegando mediante la comprobación que se ejecuta cada pocos minutos, siempre que este espacio de trabajo pueda acceder a la tienda.',
'Oc_G_First_Title' => 'La primera sincronización',
'Oc_G_First_Shop_Has' => 'La tienda ya tiene el catálogo',
'Oc_G_First_Shop_Has_Text' => 'Importe los productos en la pestaña Productos. Los productos se emparejan por modelo o SKU con sus códigos de producto y se crean si faltan; marque la opción de stock para tomar las cantidades de la tienda como stock inicial.',
'Oc_G_First_Company_Has' => '{company} tiene el catálogo',
'Oc_G_First_Company_Has_Text' => 'Envíe los productos. Los productos que faltan se crean en la tienda con su stock; los existentes se vinculan por modelo o SKU y se actualizan.',
'Oc_G_First_Both' => 'Ambos lados tienen productos',
'Oc_G_First_Both_Text' => 'Importe primero, para que los productos existentes de la tienda se vinculen en lugar de duplicarse, y después envíe para crear lo que le falte a la tienda. Mantenga iguales los códigos de producto y los modelos en ambos lados.',
'Oc_G_Stock_Master' => '{company} lleva la cifra de stock',
'Oc_G_Stock_Master_Desc' => 'Después de la primera sincronización, la cantidad de la tienda siempre se escribe desde {company}. Editar una cantidad en OpenCart no tiene efecto duradero: el siguiente movimiento o la comprobación horaria la sobrescribe.',
'Oc_G_How_Title' => 'Cómo funciona',
'Oc_G_T_Products' => 'Productos',
'Oc_G_Products_1' => 'Un producto se empareja por su código de aquí con el modelo y el SKU de la tienda. El vínculo se recuerda, así que renombrar un producto después no lo rompe.',
'Oc_G_Products_2' => 'Cuando {company} envía un producto, establece el modelo, el SKU, el nombre, el precio, el estado y el stock. La descripción, la imagen y la categoría solo se escriben cuando el producto es nuevo en la tienda o no las tiene, de modo que los textos escritos en OpenCart se conservan.',
'Oc_G_Products_3' => 'Un producto oculto en la tienda en línea o que no está a la venta aquí no se crea en la tienda; si ya está vinculado, allí se desactiva.',
'Oc_G_T_Variants' => 'Variantes y opciones',
'Oc_G_Variants_4' => 'OpenCart 4 tiene variantes reales (un producto con opciones de Color y Talla), cada una con su propio stock. Se corresponden con sus variantes en ambos sentidos, y cada una se empareja por su propio modelo.',
'Oc_G_Variants_3' => 'OpenCart 3 no tiene variantes, solo opciones, y stock por valor de opción. Un producto con una opción (por ejemplo, Talla) se sincroniza con stock por valor, que se corresponde con sus variantes. Un producto con varias opciones recibe sus opciones creadas sin stock por combinación: su stock se queda en el producto en su conjunto, y sus líneas de venta entran contra el producto.',
'Oc_G_Variants_Multi' => 'Un producto de la tienda que solo tiene opciones, sin variantes creadas, se importa como un único producto; esto se anota en los registros.',
'Oc_G_T_Stock' => 'Stock',
'Oc_G_Stock_1' => 'Con el interruptor de stock activado, cada movimiento aquí (una venta, una devolución, una compra, un ajuste, una transferencia) actualiza la tienda en segundos, después de que la página haya respondido, de modo que el cajero nunca espera a la tienda.',
'Oc_G_Stock_2' => 'Una vez por hora se comprueba y corrige cada producto vinculado, lo que cubre los cambios masivos que el envío en vivo no detecta. La pestaña Stock lo envía todo a demanda.',
'Oc_G_Stock_3' => 'Los servicios, los productos marcados como siempre en stock y los combos cuyos componentes son ilimitados se muestran como siempre disponibles en la tienda. Elija un almacén en la pestaña Conexión para contar solo ese almacén; de lo contrario, se suman todos los almacenes.',
'Oc_G_T_Orders' => 'Pedidos y estados',
'Oc_G_Orders_1' => 'La tienda anuncia al instante un pedido nuevo o modificado, y este se vuelve a leer por la conexión firmada, de modo que no se confía en nada del propio aviso. Cada pocos minutos, una comprobación recoge lo que un aviso haya pasado por alto. Cada pedido se convierte en una venta con la referencia OC-<order number>; el cliente se empareja por correo electrónico o se crea.',
'Oc_G_Col_List' => 'Lista de estados',
'Oc_G_Col_Meaning' => 'Qué hace aquí',
'Oc_G_Col_Default' => 'Establecido desde su tienda',
'Oc_G_Default_Commit' => 'Los estados que restan stock en OpenCart (Pending, Processing, Shipped, Complete de forma predeterminada)',
'Oc_G_Default_Paid' => 'Processing, Processed, Shipped, Complete',
'Oc_G_Default_Cancel' => 'Canceled, Denied, Failed, Refunded, Reversed, Chargeback, Expired, Voided',
'Oc_G_Orders_2' => 'Las listas se rellenan desde su tienda en la primera conexión y se pueden cambiar en la pestaña Conexión. Mantenga la primera lista igual que los estados que restan stock en OpenCart, para que ambos lados muevan el stock en el mismo paso.',
'Oc_G_Orders_3' => 'Un pedido con un artículo que no coincide con ningún producto queda retenido, y el producto se importa desde la tienda si existe allí. Los pedidos retenidos se reintentan en cada comprobación programada; tras doce intentos se registran y se dejan para que usted los importe a mano.',
'Oc_G_T_Cancel' => 'Cancelaciones y reembolsos',
'Oc_G_Cancel_1' => 'Cuando un pedido llega a un estado cancelado en la tienda, su venta aquí se revierte: el stock se repone, sus pagos se eliminan y la venta se borra, exactamente igual que si la eliminara en la página Ventas.',
'Oc_G_Cancel_2' => 'Una venta ya entregada, con una devolución o aceptada por una autoridad tributaria nunca se revierte desde la tienda. Se marca en sus notas y en los registros para que usted la revise.',
'Oc_G_Cancel_3' => 'Si el pedido se restablece después en la tienda, vuelve a entrar como una venta nueva.',
'Oc_G_T_Automation' => 'Interruptores de automatización',
'Oc_G_Auto_1' => 'Importar pedidos automáticamente: avisos de pedidos y la comprobación programada. Desactivado, los pedidos solo llegan cuando los importa en la pestaña Pedidos.',
'Oc_G_Auto_2' => 'Enviar stock automáticamente: actualizaciones de stock en vivo y la comprobación horaria. Desactivado, la tienda solo cambia cuando envía el stock a mano.',
'Oc_G_Auto_3' => 'Enviar cambios de productos automáticamente: un producto creado o editado aquí actualiza la tienda de inmediato. Desactivado, use la pestaña Productos.',
'Oc_G_T_Faq' => 'Preguntas',
'Oc_G_Q_Secret' => 'Probar conexión indica que el secreto no coincide',
'Oc_G_A_Secret' => 'Abra el módulo {company} Connector en OpenCart y copie de nuevo el secreto; un módulo reinstalado recibe uno nuevo. Péguelo en la pestaña Conexión y guarde antes de probar.',
'Oc_G_Q_Clock' => 'Probar conexión indica que el reloj de la tienda está demasiado desfasado',
'Oc_G_A_Clock' => 'Las solicitudes firmadas llevan la hora y se rechazan cuando los dos relojes difieren en más de cinco minutos. Ajuste la fecha y la hora en el servidor de la tienda.',
'Oc_G_Q_Redirect' => 'Probar conexión indica que la tienda redirige a otra dirección',
'Oc_G_A_Redirect' => 'Su tienda responde en una dirección distinta, normalmente https en lugar de http o con www. Use como URL de la tienda la dirección que aparece en el mensaje.',
'Oc_G_Q_Not_Answering' => 'Probar conexión indica que el conector no respondió',
'Oc_G_A_Not_Answering' => 'La dirección no es una tienda OpenCart, o el módulo no está instalado o está desactivado. Compruebe la URL de la tienda y, después, que el {company} Connector aparece como instalado y habilitado en Extensions → Modules.',
'Oc_G_Q_No_Orders' => 'Los pedidos se realizan en la tienda pero tardan minutos en aparecer',
'Oc_G_A_No_Orders' => 'La tienda no puede acceder a este espacio de trabajo, por lo que los pedidos solo llegan mediante la comprobación programada. Revise la dirección de {company} en la página del módulo: debe ser accesible desde el servidor de la tienda. Ejecutar Probar conexión la registra de nuevo.',
'Oc_G_Q_Stock_Wrong' => 'Una cantidad en la tienda es incorrecta',
'Oc_G_A_Stock_Wrong' => 'Envíe el stock en la pestaña Stock, lo que reescribe cada producto vinculado a partir de las cifras de aquí. Si sigue desajustándose, compruebe que el interruptor de stock está activado y que nadie edita cantidades en OpenCart.',
'Oc_G_Q_Out_Of_Stock' => 'Un producto aparece agotado en la tienda aunque aquí hay stock',
'Oc_G_A_Out_Of_Stock' => 'En OpenCart 3, un producto con varias opciones lleva su stock en el producto en su conjunto; compruebe la cantidad del producto en la tienda en lugar de la de sus opciones. Para cualquier producto, envíe el stock una vez y revise los registros de ese producto.',
'Oc_G_Q_Held' => 'Los registros indican que un pedido quedó retenido',
'Oc_G_A_Held' => 'Uno de sus artículos no coincide con ningún producto de aquí y no se pudo importar desde la tienda, normalmente porque el producto se eliminó allí. Cree o vincule el producto y luego importe los pedidos en la pestaña Pedidos.',
'Oc_G_Q_Deleted_Sale' => 'Eliminé una venta importada y volvió a aparecer',
'Oc_G_A_Deleted_Sale' => 'Mientras el pedido siga activo en la tienda, el siguiente aviso o comprobación lo vuelve a importar. En su lugar, cancele el pedido en la tienda, lo que revierte la venta aquí.',
'Oc_G_Q_Uninstall' => '¿Cómo desconecto la tienda?',
'Oc_G_A_Uninstall' => 'Desactive la sincronización en la pestaña Conexión; no se mueve nada mientras esté desactivada. Para quitar la integración de la tienda, desinstale el {company} Connector en Extensions → Modules.',
'Oc_Full_Guide' => 'Abrir la guía completa',
'Comm_Receipt_Account_Hint' => 'La cuenta de caja o banco de la que sale este pago. Su saldo disminuye en el importe y el libro mayor registra Gasto por comisiones de ventas (Sales Commission Expense) contra ella.',
'Comm_G_Q_Ledger' => '¿Qué efecto tiene en las cuentas el pago de una comisión?',
'Comm_G_A_Ledger' => 'Al crear un recibo y elegir una cuenta, el saldo de esa cuenta disminuye en el importe del recibo y, si los asientos automáticos están activados, se registra un asiento: débito en Gasto por comisiones de ventas (Sales Commission Expense, 5200-COMM), crédito en la cuenta de caja o banco elegida. Si no se selecciona ninguna cuenta, el crédito va a la cuenta de Caja (Cash) predeterminada y ningún saldo cambia.',
'Hide_Zero_Decimals' => 'Ocultar decimales en cero',
'Sys_Hide_Zero_Decimals_Help' => 'Muestra los importes enteros sin decimales: 100.00 pasa a ser 100, mientras que 100.50 conserva sus decimales. Solo afecta a la visualización; los valores guardados y los cálculos no cambian.',
'Sys_Currency_Position_Before_NoSpace' => 'Antes del importe, sin espacio',
'Sys_Currency_Position_After_NoSpace' => 'Después del importe, sin espacio',
'Supplier_Wallet' => 'Monedero de proveedor',
