'Supplier_Ledger' => 'Libro mayor de proveedores',
'Sys_Supplier_Wallet_Help' => 'Mantenga saldos prepagados con los proveedores: recargas, créditos por devoluciones y pago de compras desde el monedero. Requiere la función de plan Monedero de proveedor.',
'SW_Allow_Negative' => 'Permitir saldo negativo en el monedero',
'Sys_SW_Allow_Negative_Help' => 'Permite que un pago de compra deje en descubierto el monedero del proveedor en lugar de rechazarse.',
