'SW_Top_Up_Help' => 'Dinero pagado por adelantado al proveedor. Sale de la cuenta elegida y se mantiene en el monedero hasta que se gasta en compras.',
'SW_Refund_Help' => 'El proveedor devuelve en efectivo parte del anticipo. El importe sale del monedero y entra en la cuenta elegida.',
'SW_Adjust_Help' => 'Corrección manual sin movimiento de efectivo. Se requiere un motivo, que se conserva en el libro mayor.',
