'SW_Pay_From_Wallet' => 'Pagar desde el monedero del proveedor',
'SW_Pay_From_Wallet_Help' => 'El importe se toma del saldo prepagado que se tiene con este proveedor. No se necesita cuenta ni método de pago.',
'SW_Credit_To_Wallet' => 'Abonar al monedero del proveedor',
'SW_Credit_To_Wallet_Help' => 'En lugar de efectivo, el proveedor liquida esta devolución como crédito en el monedero que puede gastar en compras posteriores.',
'SW_Disabled_Hint' => 'El Monedero de proveedor está desactivado. Actívelo en Ajustes del sistema > Características (también requiere la función de plan Monedero de proveedor).',
