'Purchase_Update_Selling_Price' => 'Editar precio de venta en la compra',
'Sys_Purchase_Update_Selling_Price_Help' => 'Añade un campo de precio de venta a cada línea de compra, junto al costo. Un precio introducido ahí reemplaza el precio de venta del producto al guardar la compra; déjelo en blanco para mantener el precio actual.',
'Current_Selling_Price' => 'Precio de venta actual',
'Keep_Current_Price' => 'Déjelo en blanco para mantener el precio actual',
'Selling_Price_In_Base_Currency' => 'Introducido en la moneda base',
'Purchase_Update_Product_Cost' => 'Actualizar costo del producto en la compra',
'Sys_Purchase_Update_Product_Cost_Help' => 'Al guardar una compra recibida, el costo de cada producto pasa a ser el costo unitario neto de su línea de compra (después del descuento de la línea, sin impuestos, por unidad base). Las compras pendientes y pedidas no lo modifican.',
'Show_Stock_In_Search_Results' => 'Mostrar stock en los resultados de búsqueda',
'Show_Stock_In_Search_Results_Help' => 'Muestra la cantidad disponible de cada producto junto a él en el desplegable de búsqueda del POS.',
'Layout_6_Tabular' => 'Diseño 6 - Tabular',
'Show_Signature_Line' => 'Mostrar línea de firma',
'Show_Signature_Line_Desc' => 'Imprime una línea en blanco para la firma del cliente debajo del recibo, sea cual sea el diseño seleccionado.',
'Customer_Signature' => 'Firma del cliente',
'Set_Signature_Label' => 'Etiqueta de la línea de firma (en blanco = "Firma del cliente")',
'Oc_Code_Source' => 'Origen del código de producto',
'Oc_Code_Source_Help' => 'Qué campo de OpenCart es el código de producto aquí. El modelo es obligatorio en OpenCart, por lo que algunas tiendas escriben en él una categoría o un tipo de producto y guardan el código real del artículo en SKU, ISBN, UPC, EAN, JAN o MPN; elija ese campo para una tienda así. Cuando el campo elegido está vacío, se usa el modelo y, después, el SKU. Se aplica a los productos importados, al emparejamiento y a los envíos.',
'Oc_Code_Source_Model' => 'Modelo (predeterminado)',
'Oc_Code_Source_Sku' => 'SKU',
'Oc_Connector_Link' => 'Sitio web del conector',
'Oc_Connector_Link_Help' => 'La dirección de su sitio web. OpenCart enlaza el nombre del conector con ella en la página Extensions > Installer. Déjelo en blanco para usar la dirección de este espacio de trabajo de {company}.',
'Store_Warehouses_Help' => 'El stock que se muestra y se descuenta en línea procede de estos almacenes. Mientras "Restringir productos por almacén" esté activado en Características, la tienda también lista solo los productos que pertenecen a estos almacenes (o tienen stock en ellos).',
'Oc_Code_Source_Needs_Update' => 'El conector instalado en la tienda (versión {version}) solo informa del modelo y el SKU. Descargue de nuevo el conector y súbalo sobre el anterior en la tienda para que se lea este campo.',
'Oc_L_Title' => 'Registros de OpenCart',
'Oc_L_Intro' => 'Aquí se registra cada importación y envío de productos, actualización de stock, pedido y llamada a la tienda. Filtre por errores para ver qué falló, abra una fila para leer qué significa y qué hacer, y exporte la lista cuando necesite enviarla al soporte.',
'Oc_L_Tab_Hint' => 'La página completa de registros explica cada entrada, filtra por acción y fecha, y exporta a un archivo.',
