'Oc_L_Act_sync' => 'Sincronización',
'Oc_L_H_Secret' => 'El secreto guardado aquí no es el que tiene el módulo conector en OpenCart, por lo que la tienda rechaza todas las llamadas.',
'Oc_L_F_Secret' => 'En OpenCart, abra Extensions → Modules → el conector, copie el secreto que aparece allí, péguelo en la pestaña Conexión y guarde. Reinstalar el módulo crea un secreto nuevo.',
'Oc_L_H_Clock' => 'El reloj del servidor de OpenCart difiere demasiado del nuestro, por lo que las solicitudes firmadas parecen caducadas.',
'Oc_L_F_Clock' => 'Pida al proveedor de hosting que ajuste la hora del servidor (NTP). Una diferencia de unos pocos minutos basta para bloquear la conexión.',
'Oc_L_H_Disabled' => 'El módulo conector está instalado en OpenCart pero desactivado.',
'Oc_L_F_Disabled' => 'En OpenCart, abra Extensions → Modules → el conector y establezca Status en Enabled.',
'Oc_L_H_Unreachable' => 'La tienda no respondió en la dirección guardada, o el módulo conector no está instalado allí.',
'Oc_L_F_Unreachable' => 'Abra la URL de la tienda en un navegador para comprobar que está en línea, confirme que el módulo conector está instalado y habilitado, y compruebe que ningún firewall ni modo de mantenimiento bloquea nuestro servidor.',
'Oc_L_H_Redirect' => 'La tienda envía a los visitantes a otra dirección (por ejemplo, de http a https o a www).',
'Oc_L_F_Redirect' => 'Guarde como URL de la tienda, en la pestaña Conexión, la dirección indicada en el mensaje.',
'Oc_L_H_Not_Configured' => 'Falta la URL de la tienda o el secreto, por lo que todavía no se puede enviar nada.',
'Oc_L_F_Not_Configured' => 'Rellene la URL de la tienda y el secreto en la pestaña Conexión, guarde y ejecute Probar conexión.',
'Oc_L_H_Model_Taken' => 'Un producto enviado a la tienda tiene un código que otro producto de la tienda, o una de sus variantes, ya usa como modelo.',
'Oc_L_F_Model_Taken' => 'Cambie el código de uno de los dos productos, o importe primero los productos para que el producto existente de la tienda se vincule en lugar de crearse de nuevo.',
'Oc_L_H_Model_Missing' => 'Un producto enviado a la tienda no tiene código o no tiene nombre. OpenCart necesita ambos.',
'Oc_L_F_Model_Missing' => 'Asigne aquí un código y un nombre al producto y vuelva a enviarlo.',
'Oc_L_H_Held' => 'Se recibió un pedido, pero algunos de sus artículos no coinciden con ningún producto de aquí, por lo que está en espera y no se creó ninguna venta.',
'Oc_L_F_Held' => 'Cree o importe los productos que faltan (los artículos se listan a continuación) y vuelva a importar los pedidos. Los pedidos retenidos se reintentan automáticamente varias veces.',
'Oc_L_H_Given_Up' => 'Un pedido no se pudo importar tras varios intentos y ya no se reintenta.',
'Oc_L_F_Given_Up' => 'Asegúrese de que sus productos existen aquí y luego importe los pedidos a mano desde la pestaña Pedidos con una fecha anterior al pedido.',
'Oc_L_H_Review' => 'Un pedido se canceló en OpenCart después de que la venta de aquí se entregara o se devolviera, por lo que el stock no se revirtió automáticamente.',
'Oc_L_F_Review' => 'Abra la venta y decida si devolver los artículos o dejarla como está.',
'Oc_L_H_Reversed' => 'Un pedido se canceló en OpenCart y la venta correspondiente de aquí se revirtió, reponiendo su stock.',
'Oc_L_H_Backlog' => 'La importación programada de pedidos encontró más pedidos de los que procesa en una ejecución y continuará la próxima vez.',
'Oc_L_F_Backlog' => 'Importe los pedidos a mano desde la pestaña Pedidos para eliminar el atraso.',
'Oc_L_H_Paused' => 'Los envíos automáticos se pausaron durante un tiempo porque la tienda dejó de responder. Los cambios realizados mientras tanto se envían en cuanto vuelva a responder.',
'Oc_L_F_Paused' => 'Compruebe que la tienda está en línea. No hace falta nada más; la cola se reanuda sola.',
'Oc_L_H_Busy' => 'Dos envíos automáticos se solaparon y uno se hizo a un lado. No se perdió nada.',
'Oc_L_H_Codes_Suffixed' => 'Algunos productos importados tienen un código que aquí ya tenía otro producto de la tienda, normalmente porque el campo de código elegido está vacío o contiene un nombre de categoría. Se crearon con el id de OpenCart añadido para que no se fusionen dos productos.',
'Oc_L_F_Codes_Suffixed' => 'Rellene el campo de código (Model, SKU, ISBN…) en OpenCart para los productos listados a continuación, o elija otro Origen del código de producto en la pestaña Conexión; después restablezca los vínculos de productos e importe de nuevo.',
'Oc_L_H_Options' => 'Algunos productos de la tienda tienen opciones (talla, color…) sin stock por variante, por lo que el stock se controla para el producto en su conjunto.',
'Oc_L_F_Options' => 'No es necesario hacer nada. Para controlar el stock por opción, convierta esas opciones en variantes en OpenCart 4, o use una opción por producto en OpenCart 3.',
'Oc_L_H_Pull_Ok' => 'Esta página de productos se leyó desde la tienda. Creado significa un producto nuevo aquí; actualizado significa que ya existía y se vinculó.',
'Oc_L_H_Pull_Failed' => 'Algunos productos de esta página no se pudieron guardar aquí; cada uno se lista a continuación con el motivo.',
'Oc_L_F_Pull_Failed' => 'Corrija los productos listados en OpenCart (la causa habitual es que falte el nombre o el código) e importe de nuevo. Solo se ven afectados los que fallaron.',
'Oc_L_H_Push_Warnings' => 'Los productos se enviaron a la tienda, pero la tienda informó de problemas con algunos de ellos, como una imagen que no pudo descargar.',
'Oc_L_F_Push_Warnings' => 'Lea la lista a continuación. Las imágenes deben ser accesibles desde el servidor de la tienda; todo lo demás se guardó tal como se envió.',
'Oc_L_H_Missing_Remote' => 'Se envió el stock, pero algunos productos vinculados ya no existen en la tienda.',
'Oc_L_F_Missing_Remote' => 'Envíe los productos para volver a crearlos en la tienda, o restablezca los vínculos de productos si se eliminaron a propósito.',
'Oc_L_H_Generic' => 'Falló un paso de la sincronización. El mensaje de arriba es el motivo indicado por la propia tienda o por el servidor.',
'Oc_L_F_Generic' => 'Ejecute Probar conexión en la pestaña Conexión. Si es correcta, intente de nuevo el paso; si falla, siga la indicación que ofrece.',
'Oc_L_H_Code_Fallback' => 'Algunos productos de esta página llegaron sin valor en el campo elegido como Origen del código de producto, por lo que se usó su modelo (a menudo un nombre de categoría) como código.',
'Oc_L_F_Code_Fallback' => 'Revise "Productos con cada campo" a continuación. Si el campo elegido muestra 0 aunque la tienda sí tiene esos valores, la tienda los guarda con otro nombre de identificador; abra en OpenCart uno de los productos listados (pestaña Data, Product Codes) y envíenos lo que muestra. De lo contrario, rellene el campo en OpenCart para los productos listados e importe de nuevo.',
'Oc_L_H_Old_Connector' => 'La tienda aún ejecuta un conector anterior a la versión 1.1.0, que solo envía el modelo y el SKU, por lo que el campo de código elegido nunca llega y se usó el modelo.',
'Oc_L_F_Old_Connector' => 'Descargue de nuevo el conector, desinstale y elimine el anterior en OpenCart (Extensions → Installer), instale el nuevo, pegue su nuevo secreto en la pestaña Conexión y ejecute Probar conexión. La página debe mostrar Connector 1.1.0 antes de importar.',
'Oc_L_D_Code_Source' => 'Origen del código de producto',
'Oc_L_D_Code_Fallback_Count' => 'Productos sin el campo elegido',
'Oc_L_D_Codes_Seen' => 'Productos con cada campo',
'Oc_L_D_Code_Fallback' => 'Productos que usaron el modelo como código (#id de OpenCart, modelo)',
'Oc_L_H_Codes_Fixed' => 'Algunos productos importados anteriormente con el modelo como código ya tienen el campo elegido en la tienda, por lo que su código se corrigió con él.',
'Oc_L_D_Codes_Fixed' => 'Códigos corregidos (anterior → nuevo)',
