'LicK_G_Status' => 'Lee la licencia sin cambiar nada. Nunca concede el uso (valid siempre es false).',
'LicK_G_Request' => 'Solicitud',
'LicK_G_Request_Help' => 'Envíe un cuerpo JSON con license_key. product (el código del producto) es opcional y garantiza que la clave pertenece a su producto. Envíe domain o device_id (+ device_name opcional), obligatorio para licencias bloqueadas y para licencias con límite de activaciones. Envíe un nonce aleatorio en cada llamada y compruebe que vuelve en el token.',
'LicK_G_Response' => 'Respuesta',
'LicK_G_Response_Help' => 'valid es true solo en una respuesta de activate / validate que permite el uso en este dominio o dispositivo. status indica el estado de la licencia. Una respuesta rechazada también incluye error y message. El token repite action, key_fingerprint (SHA-256 de su clave, en mayúsculas y sin espacios al inicio ni al final), identifier, nonce y host: compruébelos.',
