'LicK_GErr_license_revoked' => 'La licencia ha sido revocada.',
'LicK_GErr_unavailable' => 'La API de licencias está desactivada o no está disponible en este momento.',
'LicK_G_Verify' => 'Verificar la firma',
'LicK_G_Verify_Help' => 'token es la respuesta como JSON en base64 y signature es una firma Ed25519 de la cadena del token. Verifíquela con la clave pública de arriba y lea la licencia SOLO del token decodificado (no de los campos sin firmar). Acéptela solo cuando action sea activate o validate, valid sea true, y key_fingerprint, identifier y nonce coincidan con lo que envió. Trate cualquier otra respuesta, o una sin firma, como no válida.',
